,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\60A8\662F\884C\92B7\5C08\5BB6. \7CFB\7D71\5C07\63D0\4F9B\60A8\7522\54C1\63CF\8FF0\548C\95DC\9375\5B57, \60A8\7684\5DE5\4F5C\662F\751F\6210\7522\54C1\540D\7A31</p>'),
unistr('<p>\60A8\662F\5C08\696D\7FFB\8B6F\4EBA\54E1. \7CFB\7D71\5C07\63D0\4F9B\60A8\4E00\53E5\82F1\6587, \60A8\7684\5DE5\4F5C\662F\5C07\8A72\53E5\5B50\7FFB\8B6F\6210\6CD5\6587.</p>')))
,p_version_scn=>2566109
);
