 p_id=>wwv_flow_imp.id(119399645512667102)
,p_name=>'PE.PROPERTY.AI_SYSTEM_PROMPT.HELP'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\6307\5B9A AI \670D\52D9\7684\8D77\59CB\6307\793A\6216\76F8\95DC\8CC7\8A0A\74B0\5883. \7CBE\5FC3\8A2D\8A08\7684\7CFB\7D71\63D0\793A\6703\5F15\5C0E AI \7684\884C\70BA\4E26\8A2D\5B9A\5176\56DE\61C9\7684\8A9E\6C23.'),
unistr('\82E5\8981\5EFA\7ACB\6709\6548\7684\7CFB\7D71\63D0\793A, \9996\5148\8981\660E\78BA\5B9A\7FA9\60A8\5E0C\671B AI \64D4\4EFB\7684\89D2\8272\6216\5177\5099\7684\5C08\696D\77E5\8B58. \63A5\4E0B\4F86, \63CF\8FF0\60A8\671F\671B AI \57F7\884C\7684\7279\5B9A\5DE5\4F5C\6216\56DE\61C9\985E\578B.</p>'),
unistr('<p>\6CE8\610F: \5982\679C\60A8\4E0D\78BA\5B9A\5982\4F55\5EFA\7ACB\6709\6548\7684\7CFB\7D71\63D0\793A, \8ACB\53C3\95B1 AI \670D\52D9\7684\6587\4EF6\4EE5\53D6\5F97\8A73\7D30\6307\5F15. \6B64\5916, \60A8\53EF\8981\6C42\751F\6210\5F0F AI \7CFB\7D71\5354\52A9\8A2D\8A08\63D0\793A.'),
unistr('\4F8B\5982, \60A8\53EF\8981\6C42<em>\300C\5354\52A9\6211\70BA AI \8F14\52A9\7A0B\5F0F\7DE8\5BEB\7CFB\7D71\63D0\793A, \5176\5DE5\4F5C\662F\5F9E\63D0\4F9B\7684\6587\5B57\64F7\53D6\76F8\95DC\6A19\8A18\6216\95DC\9375\5B57.\300D</em></p>')))
,p_version_scn=>2566090
);
