,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\6307\5B9A\56DE\61C9\7684\5275\9020\6027\548C\96A8\6A5F\6027. \8F03\4F4E\7684\6EAB\5EA6\6703\4F7F\8F38\51FA\7D50\679C\66F4\70BA\96C6\4E2D\3001\78BA\5B9A\4E14\4FDD\5B88, \50BE\5411\65BC\4E00\822C\6216\53EF\9810\6E2C\7684\7B54\6848. \8F03\9AD8\7684\6EAB\5EA6\5247\6703\63D0\9AD8\6A21\578B\5275\9020\6027, \4F7F\5F97\6A21\578B\66F4\6709\53EF\80FD\7522\751F\591A\5143\4E14\8F03\4E0D\50B3\7D71\7684\56DE\61C9. \8ACB\6839\64DA\56DE\61C9\4E2D\7CBE\78BA\5EA6\548C\5275\9020\6027\4E4B\9593\6240\9700\7684\5E73\8861\8ABF\6574\6EAB\5EA6.</p>'),
unistr('<p>\6CE8\610F: \6EAB\5EA6\6703\4F9D AI \670D\52D9\800C\6709\4E0D\540C. \5EFA\8B70\60A8\5728\9078\64C7\9069\7576\7684\503C\6642\8A55\4F30 AI \670D\52D9\7684\6EAB\5EA6\503C.</p>')))
,p_version_scn=>2566096
);
