wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(121067603261667643)
,p_name=>'PE.PROPERTY.BUILD_OPTION.EXAMPLES'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>1. \60A8\6B63\5728\958B\767C\5C07\6703\6709\8A31\591A\5B89\88DD\9805\7684\61C9\7528\7A0B\5F0F.'),
unistr('                                        \6B64\5916, \6BCF\500B\5B89\88DD\9805\53EF\9078\64C7\555F\7528\6216\505C\7528\7279\5B9A\7684\61C9\7528\7A0B\5F0F\529F\80FD.'),
unistr('                                        \4F7F\7528\300C\7D44\5EFA\9078\9805\300D, \60A8\53EF\4EE5\958B\767C\4E00\500B\61C9\7528\7A0B\5F0F, \800C\4E14\5728\61C9\7528\7A0B\5F0F\5B89\88DD\5F8C, \53EF\4EE5\5C07\7D44\5EFA\9078\9805\8A2D\5B9A\6210\5305\62EC\6216\4E0D\5305\62EC\95DC\806F\7684\61C9\7528\7A0B\5F0F\529F\80FD.'),
unistr('                                        \60A8\4E5F\53EF\4EE5\4F7F\7528 API \5728\61C9\7528\7A0B\5F0F\5167\516C\958B\6B64\529F\80FD.'),
unistr('                                        \5982\6B64, \5177\5099\6B0A\9650\7684\4E00\822C\4F7F\7528\8005\5373\53EF\9078\64C7\555F\7528\6216\505C\7528\61C9\7528\7A0B\5F0F\529F\80FD.</p>'),
unistr('                                      <p>2. \60A8\6B63\5728\958B\767C\5C1A\672A\5B8C\6210\7684\529F\80FD, \56E0\6B64\4E0D\60F3\8B93\4E00\822C\4F7F\7528\8005\898B\5230.'),
unistr('									    \4F7F\7528\300C\7D44\5EFA\9078\9805\300D, \60A8\5C31\53EF\4EE5\5728\5C07\61C9\7528\7A0B\5F0F\5EFA\7F6E\5230\6E2C\8A66\548C\751F\7522\74B0\5883\5F8C, \505C\7528\61C9\7528\7A0B\5F0F\7684\9019\9805\529F\80FD.'),
unistr('									    \6B64\65B9\6CD5\7684\512A\9EDE\662F\4ECD\7136\53EF\4EE5\90E8\7F72\61C9\7528\7A0B\5F0F, \4F46\4E0D\8981\5305\62EC\672A\5B8C\6210\7684\529F\80FD.</p>'),
unistr('                                      <p>3. \60A8\6B63\5728\79FB\9664\8A8D\70BA\61C9\7528\7A0B\5F0F\4E0D\9700\8981\7684\529F\80FD, \4F46\4E0D\78BA\5B9A\9019\662F\4E0D\662F\5B89\5168\7684\4F5C\696D.'),
unistr('									    \5728\6B64\60C5\6CC1\4E0B, \60A8\53EF\4EE5\4F7F\7528\300C\7D44\5EFA\9078\9805\300D\5F9E\6839\672C\4E0A\300C\62FF\6389\300D\7279\5B9A\529F\80FD.'),
unistr('									    \82E5\5728\90E8\7F72\6642\8A8D\70BA\79FB\9664\7684\529F\80FD\662F\5FC5\8981\7684, \53EF\4EE5\5C07\5B83\6062\5FA9.'),
unistr('									    \5982\679C\8A8D\5B9A\6B64\529F\80FD\4E26\975E\5FC5\8981, \5C31\53EF\4EE5\653E\5FC3\5730\5C07\5B83\81EA\61C9\7528\7A0B\5F0F\4E2D\79FB\9664.</p>')))
,p_version_scn=>2566354
);
