,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\82E5\5DF2\9001\51FA\9801\9762\4E14\6B64\5C6C\6027\8A2D\70BA<strong>\958B\555F</strong>, \4FBF\6703\5728\4F3A\670D\5668\7AEF\57F7\884C\70BA\9801\9762\5B9A\7FA9\7684\6240\6709\9A57\8B49\8207\5167\5EFA\9A57\8B49 (\4F8B\5982\5FC5\8981\3001\6709\6548\6578\5B57\6216\6709\6548\65E5\671F).'),
unistr('\6B64\5916, \82E5\61C9\7528\7A0B\5F0F\7684<em>\76F8\5BB9\6027\6A21\5F0F</em>\8A2D\70BA <strong>5.1</strong> \6216\4EE5\4E0A, &PRODUCT_NAME. \9084\6703\57F7\884C\5F9E\5C6C\7AEF\9A57\8B49, \4F8B\5982\5FC5\8981\7684\9805\76EE. \8ACB\53C3\95B1\300C\7248\6B21\6CE8\610F\4E8B\9805\300D\4E2D\7684\300C\76F8\5BB9\6027\6A21\5F0F\300D, \77AD\89E3\9032\4E00\6B65\7684\8A73\7D30\8CC7\8A0A.'),
unistr('\9664\975E\6240\6709\554F\984C\5747\5DF2\4FEE\6B63, \5426\5247\4E0D\6703\9001\51FA\9801\9762.</p>'),
unistr('<p>\82E5\8A2D\70BA<strong>\95DC\9589</strong>, \5247\4E0D\6703\57F7\884C\5B9A\7FA9\7684\9A57\8B49, \4E5F\4E0D\6703\57F7\884C\5167\5EFA\9A57\8B49.'),
unistr('\82E5\8981\5FFD\7565\6B64\8A2D\5B9A\4E26\57F7\884C\7279\5B9A\9A57\8B49, \8ACB\4FEE\6539\9A57\8B49\4E26\5C07\9A57\8B49\5C6C\6027<strong>\4E00\5F8B\57F7\884C</strong>\8A2D\70BA<strong>\958B\555F</strong>.</p>'),
unistr('<p>\5C0D\65BC\4E0D\61C9\57F7\884C\5927\90E8\5206\9A57\8B49\7684\300C\522A\9664\300D\6216\300C\53D6\6D88\300D\7B49\6309\9215, \6B64\5C6C\6027\7279\5225\6709\7528.'),
unistr('\82E5\9805\76EE\662F\7A7A\503C\6216\932F\8AA4\985E\578B, \901A\5E38\4E0D\61C9\963B\6B62\4F7F\7528\8005\57F7\884C\6B64\985E\52D5\4F5C.'),
