wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(120538151663667456)
,p_name=>'PE.PROPERTY.DATABASE_OPERATION.HELP'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    \6307\5B9A<strong>\8CC7\6599\5EAB\4F5C\696D</strong>\7D66\6B64 HTTP \4F5C\696D. \8CC7\6599\5EAB\4F5C\696D\662F\8B93 &PRODUCT_NAME. \5143\4EF6\80FD\5920\8207 REST \8CC7\6599\4F86\6E90\642D\914D\904B\4F5C\7684\91CD\8981\5143\7D20. \6BCF\500B &PRODUCT_NAME. \5143\4EF6\90FD\6703\6709\4E00\500B\6307\5B9A\7684 REST \8CC7\6599\4F86\6E90 (\800C\4E0D\662F\4F5C\696D), \56E0\6B64\5B83\6703\6839\64DA\6240\9700\7684\8CC7\6599\5EAB\4F5C\696D\67E5\5C0B HTTP \4F5C\696D. '),
'</p>',
'<ul>',
unistr('    <li>\8996\89BA\5316\5143\4EF6 (\4F8B\5982\5831\8868\3001\5716\8868\3001CSS \884C\4E8B\66C6\7B49\7B49) \4E00\5F8B\6703\4F7F\7528\6307\5B9A\7D66<strong>\64F7\53D6\8CC7\6599\5217</strong>\8CC7\6599\5EAB\4F5C\696D\7684 HTTP \4F5C\696D. <strong>APEX_EXEC.OPEN_WEB_SOURCE_QUERY</strong> \4E5F\6703\4F7F\7528\64F7\53D6\8CC7\6599\5217\8CC7\6599\5EAB\4F5C\696D.</li>'),
unistr('    <li>\8868\55AE\5143\4EF6\5728\63D2\5165\3001\66F4\65B0\6216\522A\9664\8CC7\6599\5217\6642, \6703\5206\5225\4F7F\7528\6307\5B9A\7D66<strong>\63D2\5165\8CC7\6599\5217</strong>\3001<strong>\66F4\65B0\8CC7\6599\5217</strong>\6216<strong>\522A\9664\8CC7\6599\5217</strong>\7684\4F5C\696D. \5728 PL/SQL \4E2D, <strong>APEX_EXEC.OPEN_WEB_SOURCE_DML_CONTEXT</strong> \7B49\540C\65BC\8868\55AE.</li>'),
unistr('    <li>\57F7\884C\907A\5931\7684\66F4\65B0\5075\6E2C\6216\5141\8A31\7684\4F5C\696D\6AA2\67E5\6642, \8868\55AE\5143\4EF6\6703\4F7F\7528<strong>\64F7\53D6\55AE\4E00\8CC7\6599\5217</strong>\8CC7\6599\5EAB\4F5C\696D. \8868\55AE\63A5\8457\6703\5728\57F7\884C\771F\6B63\7684 DML \4F5C\696D\4E4B\524D, \4F7F\7528\6B64\4F5C\696D\5F9E REST \670D\52D9\91CD\65B0\64F7\53D6\8CC7\6599\5217.</li>'),
unistr('    <li>&PRODUCT_NAME. \5143\4EF6\4E0D\6703\4F7F\7528\672A\5C0D\61C9\5230\8CC7\6599\5EAB\4F5C\696D\7684\4F5C\696D. \4F7F\7528 <strong>APEX_EXEC.EXECUTE_WEB_SOURCE</strong> PL/SQL \7A0B\5E8F\53EF\5F9E PL/SQL \76F8\95DC\8CC7\8A0A\74B0\5883\57F7\884C\9019\4E9B\672A\5C0D\61C9\7684\4F5C\696D.</li>'),
'</ul>',
'<p>',
'    <br>',
unistr('    \8209\4F8B\4F86\8AAA, &PRODUCT_NAME. \7684\5831\8868\6216\5716\8868\5143\4EF6\9700\8981\4E00\7D44\8CC7\6599\5217. \5728\8207 REST \8CC7\6599\4F86\6E90'),
unistr('    \642D\914D\904B\4F5C\6642, &PRODUCT_NAME. \5C07\6703\67E5\5C0B<strong>\64F7\53D6\8CC7\6599\5217</strong>\8CC7\6599\5EAB\4F5C\696D\4E26\65BC'),
unistr('    \7A0B\5F0F\5BE6\969B\57F7\884C\6642\57F7\884C\6307\5B9A\7684 HTTP \4F5C\696D. \8868\55AE\5C07\5C0B\627E\63D2\5165\8CC7\6599\5217\3001\66F4\65B0\8CC7\6599\5217\6216\522A\9664\8CC7\6599\5217\7B49\8CC7\6599\5EAB\4F5C\696D.'),
'</p>',
'<p>',
unistr('    \6BCF\500B\8CC7\6599\5EAB\4F5C\696D\5728 REST \8CC7\6599\4F86\6E90\5167\53EA\80FD\6307\5B9A\4E00\6B21. &PRODUCT_NAME. \5143\4EF6\5F9E\5BE6\969B HTTP \4F5C\696D\7684\62BD\8C61\65B9\5F0F, \53EF\4EE5\5EFA\7ACB\4E0D\540C\884C\70BA\7684\65B0\4F5C\696D, \4E26\5C07\65B0\4F5C\696D\6307\5B9A\7D66\8CC7\6599\5EAB\4F5C\696D. \6240\6709\5143\4EF6\518D\4EE5\901A\900F\65B9\5F0F\4F7F\7528\65B0\7684 HTTP \4F5C\696D.'),
'</p>',
'<p>',
unistr('    HTTP \4F5C\696D (GET\3001POST\3001PUT\3001DELETE) \8207\8CC7\6599\5EAB\4F5C\696D\7684\5C0D\61C9\4E26\7121\9650\5236. POST HTTP \4F5C\696D\53EF\4EE5\5C0D\61C9\5230\64F7\53D6\8CC7\6599\5217\8CC7\6599\5EAB\4F5C\696D. \4E0D\904E, \70BA\4E86\660E\78BA\6027\548C\7DAD\8B77\65B9\9762\7684\8003\91CF, \5EFA\8B70\60A8\5728\8A2D\8A08 REST API \6642, \4F7F\7528 GET \9032\884C\64F7\53D6\4F5C\696D, \4F7F\7528 POST\3001PUT\3001DELETE \8B8A\66F4\8CC7\6599.'),
'</p>'))
,p_version_scn=>2566261
);
