unistr('\5B83\53EF\7528\4F86\91CB\653E\6216\6E05\9664\5DF2\4F7F\7528\7684\8CC7\6E90 (\4F8B\5982 VPD \76F8\95DC\8CC7\8A0A\74B0\5883\6216\8CC7\6599\5EAB\9023\7D50).'),
'</p>',
unistr('<p>\7BC4\4F8B 1:'),
'<pre>',
'dbms_session.clear_context(''CTX_USER_QRY'');',
'</pre>',
unistr('\6B64\547C\53EB\6703\5148\91CD\8A2D\540D\70BA CTX_USER_QRY \7684\61C9\7528\7A0B\5F0F\76F8\95DC\8CC7\8A0A\74B0\5883, \518D\5C07\8CC7\6599\5EAB\968E\6BB5\4F5C\696D\9001\56DE\968E\6BB5\4F5C\696D\96C6\5340,'),
unistr('\4EE5\78BA\4FDD\5728\4E4B\5F8C\91CD\8907\4F7F\7528\6642\5C07\4E0D\6703\6D29\6F0F\4EFB\4F55\8CC7\8A0A.'),
'</p>',
unistr('<p>\7BC4\4F8B 2:'),
'<pre>',
'dbms_session.close_database_link(''SALES'');',
'</pre>',
unistr('\6B64\547C\53EB\6703\95DC\9589\53EF\80FD\5DF2\5728\300C\521D\59CB\5316 PL/SQL \7A0B\5F0F\78BC\300D\4E2D\958B\555F\6216\900F\904E\9023\7D50\67E5\8A62\8CC7\6599\96B1\542B\5730\958B\555F\7684\8CC7\6599\5EAB\9023\7D50 SALES.'),
unistr('\518D\6B21\63D0\9192, \9019\6703\91CB\653E\8CC7\6E90, \4E26\5728\91CD\8907\4F7F\7528\8CC7\6599\5EAB\968E\6BB5\4F5C\696D\6642\9632\6B62\8CC7\6E90\6D41\5931.'),
'</p>'))
,p_version_scn=>2566221
);
