wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(120333313893667391)
,p_name=>'PE.PROPERTY.DB_SESSION_INIT.HELP'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>\60A8\53EF\4EE5\5229\7528\6B64\5C6C\6027\8F38\5165 PL/SQL \5340\584A, \4EE5\8A2D\5B9A\8207\76EE\524D\7684\300C\986F\793A\9801\9762\300D\6216\300C\63A5\53D7\9801\9762\300D\8981\6C42\95DC\806F\4E4B\8CC7\6599\5EAB\968E\6BB5\4F5C\696D\7684\76F8\95DC\8CC7\8A0A\74B0\5883. \60A8\5728\6B64\8655\8F38\5165\7684\5340\584A\6703\5728\9032\884C\9801\9762\8981\6C42\6642, \5728\5EFA\7ACB <code>APP_USER</code> \503C\4E4B\5F8C\7ACB\5373\57F7\884C. <code>APP_USER</code> (\4F7F\7528 <code>:APP_USER</code> \6216 <code>v(''APP_USER'')</code>) \7684\503C\53EF\5728\5340\584A\5167\4F7F\7528. \4E5F\53EF\4EE5\53C3\7167\968E\6BB5\4F5C\696D\72C0\614B\4E2D\5176\4ED6\9805\76EE\7684\503C, \4F46\9019\985E\9805\76EE\5FC5\9808\662F\8D77\59CB\76EE\524D\7684\9801\9762\8981\6C42\524D,')
||unistr(' \5C31\5DF2\5728\968E\6BB5\4F5C\696D\72C0\614B\4E2D\5EFA\7ACB\7684\9805\76EE.'),
unistr('\8ACB\53C3\8003\4E0B\5217\7BC4\4F8B:'),
'</p>',
'<pre>',
'dbms_session.set_context(''CTX_USER_QRY'',''USERPRIV'',my_package.my_function(:APP_USER));',
'</pre>',
'',
unistr('<p>\6B64\7BC4\4F8B\5728\540D\70BA <code>CTX_USER_QRY</code> \7684\76F8\95DC\8CC7\8A0A\74B0\5883\4E2D, \5C07 <code>USERPRIV</code> \7684\503C\8A2D\70BA\5957\88DD\7A0B\5F0F <code>my_package</code> \4E2D\51FD\6578 <code>my_function</code> \50B3\56DE\7684\503C. \51FD\6578\6703\5C07\76EE\524D\7684 <code>APP_USER</code> \503C\7576\4F5C\8F38\5165\5F15\6578\50B3\9001. \56E0\6B64\53EF\4EE5\5047\5B9A, \6703\5728 VPD \539F\5247 (\5DF2\5728\61C9\7528\7A0B\5F0F\7684\5256\6790\7DB1\8981\5167\5EFA\7ACB) \4E2D\4F7F\7528\6307\5B9A\7684\76F8\95DC\8CC7\8A0A\74B0\5883, \4EE5\7522\751F\8A8D\8B49\4E4B\4F7F\7528\8005\9069\7528\7684\8FF0\8A5E.</p>'),
'',
unistr('<p>\300C\865B\64EC\5C08\7528\8CC7\6599\5EAB\300D\4E5F\7A31\70BA\300C\5FAE\9EDE\5B58\53D6\63A7\5236\300D\6216 FGAC, \662F\4E00\9805\63D0\4F9B\61C9\7528\7A0B\5F0F\8A2D\8A08\4ECB\9762 (API) \7684 Oracle \8CC7\6599\5EAB\529F\80FD, \8B93\958B\767C\4EBA\54E1\53EF\4EE5\6307\5B9A\5B89\5168\6027\539F\5247\7D66\8CC7\6599\5EAB\8868\683C\548C\8996\89C0\8868. \958B\767C\4EBA\54E1\53EF\4EE5\5229\7528 PL/SQL, \5728\9810\5B58\7A0B\5E8F\5EFA\7ACB\5B89\5168\6027\539F\5247, \7136\5F8C\547C\53EB RDBMS \5957\88DD\7A0B\5F0F, \5C07\7A0B\5E8F\9023\7D50\5230\8868\683C\6216\8996\89C0\8868. \6B64\985E\539F\5247\4EE5\8CC7\6599\5EAB\5167\5132\5B58\7684\61C9\7528\7A0B\5F0F\8CC7\6599\5167\5BB9\70BA\57FA\790E, \6216\4EE5 Oracle \8CC7\6599\5EAB\63D0\4F9B\7684\76F8\95DC\8CC7\8A0A\74B0\5883\8B8A\6578\70BA\57FA\790E. \6240\4EE5, VPD \5141\8A31\79FB\9664\61C9\7528\7A0B\5F0F\7684\5B58\53D6\5B89\5168\6027\6A5F\5236, \4E14\66F4\9069\7528\65BC\7279\5B9A\7DB1\8981.</p>'),
'',
unistr('<p>\6B64\8655\8F38\5165\7684\7A0B\5F0F\78BC\5FC5\9808\4E0D\9644\5C6C\65BC VPD/FGAC, \4E14\5FC5\9808\8207\5B89\5168\6027\5B8C\5168\7121\95DC. \6240\6709\5FC5\9808\5728\6700\958B\59CB\8981\6C42\9801\9762\6642\57F7\884C\7684\7A0B\5F0F\78BC\5747\53EF\7F6E\65BC\6B64\8655. \4F8B\5982, \4E0B\5217\7A0B\5F0F\78BC\8A2D\5B9A\6BCF\500B\9801\9762\8981\6C42\7684\8CC7\6599\5EAB\968E\6BB5\4F5C\696D\6642\5340:</p>'),
'',
'<pre>',
'BEGIN',
'   EXECUTE IMMEDIATE ''alter session set time_zone = ''''Australia/Sydney'''' '';',
'END;',
'</pre>'))
,p_version_scn=>2566221
);
