wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(119965366246667277)
,p_name=>'PE.PROPERTY.ERROR_HANDLING_FUNCTION.HELP'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\8F38\5165\61C9\7528\7A0B\5F0F\5167\767C\751F\932F\8AA4\6642, \8981\547C\53EB\7684 PL/SQL \51FD\6578\540D\7A31.'),
unistr('\60A8\53EF\4EE5\4F7F\7528\6B64\51FD\6578\4F86\8655\7406\5404\7A2E\932F\8AA4\4EE3\78BC, \5305\62EC\4F86\81EA Oracle Database \7684\932F\8AA4, \4E26\4F9D\7167\9700\6C42\5C07\9019\985E\932F\8AA4\8A18\9304\5728\60A8\5B9A\7FA9\7684\81EA\8A02\8868\683C\4E2D.'),
unistr('\51FD\6578\53EF\5305\542B\908F\8F2F\4EE5\4FBF\4FEE\6539\932F\8AA4\8A0A\606F\8207\986F\793A\4F4D\7F6E, \5C07 Oracle Database \932F\8AA4\8F49\63DB\70BA\4F7F\7528\8005\6613\65BC\7406\89E3\7684\8A0A\606F.'),
unistr('\4F8B\5982, \60A8\53EF\4EE5\5728 <code>DEMO_CUSTOMERS</code> \64F7\53D6\552F\4E00\7D22\5F15\9375\9055\898F, \4E26\5C07 <code>ORA-00001</code> \8A0A\606F\53D6\4EE3\70BA\6B64\6587\5B57: \300C\81EA\8A02\540D\7A31\300D\5FC5\9808\662F\552F\4E00\540D\7A31.'),
unistr('\5F9E\914D\7F6E\5EAB\5B89\88DD <strong>Poll</strong> \5165\9580\61C9\7528\7A0B\5F0F\6703\5EFA\7ACB <code>EBA_QPOLL_FW</code> \5957\88DD\7A0B\5F0F, \5176\4E2D\5305\62EC <code>apex_error_handling</code> \51FD\6578.'),
unistr('\6B64\932F\8AA4\8655\7406\51FD\6578\5305\542B\8A73\76E1\7684\8A3B\89E3, \65B9\4FBF\60A8\4F5C\70BA\81EA\884C\5B9A\7FA9\51FD\6578\7684\57FA\790E.</p>'),
unistr('<p>\8F38\5165\7684\51FD\6578\540D\7A31\53EF\4EE5\53C3\7167\8CC7\6599\5EAB\4E2D\7684\5957\88DD\7A0B\5F0F\51FD\6578\6216\7368\7ACB\51FD\6578. \4F8B\5982:'),
'<pre>',
'log_apex_error',
'</pre>',
'</p>',
unistr('<p>\7576\53C3\7167\8CC7\6599\5EAB PL/SQL \5957\88DD\7A0B\5F0F\6216\7368\7ACB\51FD\6578\6642, \60A8\53EF\4EE5\4F7F\7528 <code>#OWNER#</code> \66FF\4EE3\5B57\4E32\4F86\53C3\7167\76EE\524D\61C9\7528\7A0B\5F0F\7684\5256\6790\7DB1\8981. \4F8B\5982:'),
'<pre>#OWNER#.log_apex_error</pre>',
'</p>',
unistr('<p>\82E5\5728\9801\9762\6307\5B9A\932F\8AA4\8655\7406\51FD\6578, \8A72\9801\9762\5C07\4F7F\7528\6B64\51FD\6578, \800C\975E\6309\7167\6B64\61C9\7528\7A0B\5F0F\5C64\7D1A\7684\8A2D\5B9A.</p>'),
unistr('<p>\300C\932F\8AA4\8655\7406\51FD\6578\300D\5FC5\9808\5BE6\884C\4E0B\5217\4ECB\9762:'),
'<pre>',
'function &lt;name of function> (',
'    p_error in apex_error.t_error )',
'    return apex_error.t_error_result',
'</pre>',
'</p>',
unistr('<p>\8ACB\53C3\95B1 API Reference \624B\518A, \77AD\89E3\5957\88DD\7A0B\5F0F <code>apex_error</code> \7684\63CF\8FF0.</p>')))
,p_version_scn=>2566169
);
