unistr('\82E5\767C\751F\7121\6CD5\8655\7406\7684\7570\5E38\72C0\6CC1, \5247\986F\793A\6B64\8A0A\606F. \5728\932F\8AA4\8655\7406\505C\6B62\5F8C, \6703\9032\884C\5012\56DE\4E26\986F\793A\932F\8AA4\8A0A\606F.</p>'),
unistr('<p>\6CE8\610F: \82E5\5DF2\5B9A\7FA9<strong>\767C\751F\932F\8AA4\7684\9801\9762</strong>\4F5C\70BA\932F\8AA4\986F\793A\4F4D\7F6E, \5247\9810\8A2D\6703\986F\793A SQL \932F\8AA4\8A0A\606F sqlerrm, \56E0\6B64\4E0D\9700\8981\5728\60A8\7684\932F\8AA4\5167\5BB9\4E2D\52A0\4E0A <code>#SQLERRM#</code>.</p>'),
unistr('<p>\932F\8AA4\8A0A\606F\53EF\5305\62EC\4E0B\5217\66FF\4EE3\5B57\4E32:</p>'),
'<dl>',
'  <dt><code>#SQLERRM_TEXT#</code></dt>',
