wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(119381336224667096)
,p_name=>'PE.PROPERTY.ERROR_MESSAGE.COMPONENT_PROPERTY.VALIDATION.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\53EF\5B58\53D6\7684\932F\8AA4\5EFA\8B70\8B93\4F7F\7528\8005\9AD4\9A57\66F4\5177\5305\5BB9\6027, \53EF\5354\52A9\4E0D\540C\80FD\529B\7684\4F7F\7528\8005\4EE5\6709\6548\7387\7684\65B9\5F0F\66F4\6B63\8F38\5165\932F\8AA4.</p>'),
unistr('<strong>\6700\4F73\505A\6CD5:</strong>'),
'<ol>',
unistr('<li><strong>\6E05\695A\4E14\5177\63CF\8FF0\6027:</strong> \932F\8AA4\8A0A\606F\61C9\4EE5\7C21\6F54\4E14\6613\61C2\7684\65B9\5F0F, \6E05\695A\63CF\8FF0\4F7F\7528\8005\6240\9047\5230\7684\554F\984C. \61C9\907F\514D\4F7F\7528\53EF\80FD\6703\8B93\4F7F\7528\8005\6DF7\6DC6\7684\6280\8853\8853\8A9E\6216\542B\7CCA\4E0D\6E05\7684\8A9E\8A00.</li>'),
unistr('<li><strong>\63D0\4F9B\89E3\6C7A\65B9\5F0F:</strong> \63D0\4F9B\4F7F\7528\8005\5982\4F55\89E3\6C7A\932F\8AA4\7684\660E\78BA\6307\793A\6216\5EFA\8B70.</li>'),
unistr('<li><strong>\932F\8AA4\8B58\5225:</strong> \6E05\695A\8B58\5225\89F8\767C\932F\8AA4\7684\6B04\4F4D\6216\8F38\5165\5143\7D20. \63D0\4F9B\5145\5206\7684\76F8\95DC\5167\5BB9\4EE5\5354\52A9\4F7F\7528\8005\77AD\89E3\9700\8981\6CE8\610F\7684\8868\55AE\6216\61C9\7528\7A0B\5F0F\90E8\5206.</li>'),
unistr('<li><strong>\4E00\81F4\6027:</strong> \8B93\6574\500B\61C9\7528\7A0B\5F0F\6216\7DB2\7AD9\4E4B\932F\8AA4\8A0A\606F\7684\683C\5F0F\8207\6A23\5F0F\4FDD\6301\4E00\81F4. \4E00\81F4\7684\932F\8AA4\8A0A\606F\53EF\5354\52A9\4F7F\7528\8005\66F4\6709\6548\5730\77AD\89E3\53CA\700F\89BD\4ECB\9762.</li>'),
'</ol>',
unistr('<strong>\7BC4\4F8B:</strong>'),
'<ul>',
unistr('<li>\932F\8AA4: "\96FB\5B50\90F5\4EF6\5730\5740\7121\6548. \8ACB\8F38\5165\6709\6548\7684\96FB\5B50\90F5\4EF6\683C\5F0F (\4F8B\5982, example@example.com)."</li>'),
unistr('<li>\932F\8AA4: "\8CC7\91D1\4E0D\8DB3. \8ACB\589E\52A0\5E33\6236\7684\8CC7\91D1\4EE5\5B8C\6210\4EA4\6613."</li>'),
'</ul>'))
,p_version_scn=>2566088
);
