,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\6388\6B0A\914D\7F6E\7B2C\4E00\6B21\5728\968E\6BB5\4F5C\696D\4E2D\4F7F\7528\6642\6703\9032\884C\8A55\4F30.'),
unistr('\9078\53D6\9069\7576\7684\8A55\4F30\9EDE, \4EE5\6C7A\5B9A\6307\5B9A\6388\6B0A\7684\5F8C\7E8C\4F7F\7528\662F\5F9E\8A18\61B6\9AD4\53D6\5F97\7D50\679C, \9084\662F\91CD\65B0\8A55\4F30\6388\6B0A\914D\7F6E.</p>'),
