unistr('\5982\679C\6388\6B0A\6AA2\67E5\53D6\6C7A\65BC\8B8A\5316\7684\968E\6BB5\4F5C\696D\72C0\614B\6216\5728\6574\500B\968E\6BB5\4F5C\696D\4E0D\4E00\81F4\7684\5176\4ED6\56E0\7D20, \5247\61C9\8A72\9078\64C7\53E6\4E00\500B\503C.'),
unistr('<em>\6BCF\4E00\500B\5143\4EF6\4E00\6B21</em>\548C<em>\4E00\5F8B\8A55\4F30 (\4E0D\5FEB\53D6)</em> \9078\9805\63D0\4F9B\6388\6B0A\914D\7F6E\53EF\7528\4F86\5B9A\7FA9\7684\984D\5916\53C3\6578.'),
unistr('\5728\6388\6B0A Plug-in \4E2D, \60A8\53EF\4EE5\4F7F\7528 <em>t_authorization</em> \53C3\6578\7684 <em>component.type</em>\3001<em>component.id</em> \8207 <em>component.name</em> \5C6C\6027.'),
unistr('\5C0D\65BC\5167\5EFA\7684<em>\5B58\5728 SQL \67E5\8A62</em>\8207<em>\50B3\56DE\5E03\6797\503C\7684 PL/SQL \51FD\6578\4E3B\9AD4</em>\985E\578B, \53EF\4F7F\7528\5C0D\7B49\7684\9023\7D50\8B8A\6578 <em>:APP_COMPONENT_TYPE</em>\3001<em>:APP_COMPONENT_ID</em> \8207 <em>:APP_COMPONENT_NAME</em>.'),
