,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\8ACB\9078\53D6\4E00\500B\4F9B\7528\65BC\5B9A\7FA9\6B64\9805\76EE\6A19\7C64\4E4B\5916\89C0\548C\7248\9762\914D\7F6E\7684\6A19\7C64\6A23\677F.</p>'),
unistr('        <p>\6A19\7C64\6A23\677F\5B9A\7FA9\65BC\61C9\7528\7A0B\5F0F\4E3B\984C\4E2D.'),
unistr('        \9805\76EE\5EFA\7ACB\4E4B\5F8C, \6B64\6A23\677F\5C31\6703\81EA\52D5\8A2D\70BA\76EE\524D\4E3B\984C\4E2D\5B9A\7FA9\7684\9810\8A2D\9805\76EE\6A23\677F.</p>'),
unistr('        <p>\8A31\591A\4E3B\984C\90FD\5305\542B\53EF\7528\65BC\986F\793A\5FC5\8981\3001\9078\64C7\6027\4EE5\53CA\96B1\85CF\4E4B\6A19\7C64\7684\6A19\7C64\6A23\677F.<br>'),
unistr('        \300C\901A\7528\4E3B\984C\300D\63D0\4F9B\4E0B\5217\6A19\7C64\6A23\677F:'),
'          <dl>',
unistr('            <dt>\96B1\85CF</dt>'),
unistr('              <dd>\756B\9762\4E2D\82E5\4E0D\61C9\8A72\986F\793A\6A19\7C64\6642, \8ACB\4F7F\7528\6B64\9805. \8ACB\6CE8\610F,\300C\8F14\52A9\6280\8853\300D\4ECD\7136\53EF\4EE5\6717\8B80\6A19\7C64.'),
unistr('              \82E5\70BA\6838\53D6\65B9\584A\9805\76EE\5247\6703\5FFD\7565\96B1\85CF, \56E0\70BA\6838\53D6\65B9\584A\5F8C\65B9\5FC5\9808\986F\793A\6A19\7C64.</dd>'),
unistr('            <dt>\9078\64C7\6027</dt>'),
unistr('              <dd>\82E5\70BA\9078\64C7\6027\8868\55AE\9805\76EE, \8ACB\4F7F\7528\6B64\9805. \6A19\7C64\5C07\986F\793A\65BC\9805\76EE\7684\65C1\908A.</dd>'),
unistr('            <dt>\9078\64C7\6027 - \4E0A\65B9</dt>'),
unistr('              <dd>\82E5\70BA\9078\64C7\6027\8868\55AE\9805\76EE, \8ACB\4F7F\7528\6B64\9805. \6A19\7C64\5C07\986F\793A\65BC\9805\76EE\4E0A\65B9.</dd>'),
unistr('            <dt>\9078\64C7\6027 - \6D6E\52D5</dt>'),
unistr('              <dd>\82E5\70BA\9078\64C7\6027\8868\55AE\9805\76EE, \8ACB\4F7F\7528\6B64\9805. \6A19\7C64\5C07\986F\793A\65BC\8F38\5165\9805\76EE\5167\90E8, \7576\8F38\5165\6B04\4F4D\5305\542B\503C\6642\6703\81EA\52D5\7E2E\6E1B.</dd>'),
unistr('            <dt>\5FC5\8981</dt>'),
unistr('              <dd>\6B64\6A19\7C64\6A23\677F\6703\5728\6A19\7C64\65C1\986F\793A\4E00\500B\7D05\8272\661F\865F, \9069\7528\65BC\9700\8981\4F7F\7528\8005\8F38\5165\7684\8868\55AE\9805\76EE.  \6A19\7C64\5C07\986F\793A\65BC\9805\76EE\7684\65C1\908A.</dd>'),
unistr('            <dt>\5FC5\8981 - \4E0A\65B9</dt>'),
unistr('              <dd>\6B64\6A19\7C64\6A23\677F\6703\5728\6A19\7C64\65C1\986F\793A\4E00\500B\7D05\8272\661F\865F, \9069\7528\65BC\9700\8981\4F7F\7528\8005\8F38\5165\7684\8868\55AE\9805\76EE.  \6A19\7C64\5C07\986F\793A\65BC\9805\76EE\4E0A\65B9. \60A8\53EF\4EE5\4F7F\7528\9805\76EE\6A23\677F\4F86\5B9A\7FA9\4E3B\984C\7684\4F7F\7528\8005\4ECB\9762\5C6C\6027, \4E26\5728\8A31\591A\9801\9762\9805\76EE\9593\5171\7528\8A72\5B9A\7FA9.</dd>'),
unistr('            <dt>\5FC5\8981 - \6D6E\52D5</dt>'),
unistr('              <dd>\6B64\6A19\7C64\6A23\677F\6703\5728\6A19\7C64\65C1\986F\793A\4E00\500B\7D05\8272\661F\865F, \9069\7528\65BC\9700\8981\4F7F\7528\8005\8F38\5165\7684\8868\55AE\9805\76EE.  \6A19\7C64\5C07\986F\793A\65BC\8F38\5165\9805\76EE\5167\90E8, \7576\8F38\5165\6B04\4F4D\5305\542B\503C\6642\6703\81EA\52D5\7E2E\6E1B. \60A8\53EF\4EE5\4F7F\7528\9805\76EE\6A23\677F\5C07\4F7F\7528\8005\4ECB\9762\5C6C\6027\5B9A\7FA9\6210\70BA\4E3B\984C\7684\4E00\90E8\5206, \4E26\5728\8A31\591A\9801\9762\9805\76EE\4E4B\9593\5171\7528\8A72\5B9A\7FA9.</dd>'),
'          </dl>',
unistr('          \53E6\8ACB\53C3\95B1: <a rel="noopener noreferrer" target="_blank" href="https://apex.oracle.com/ut">\901A\7528\4E3B\984C\7BC4\4F8B\61C9\7528\7A0B\5F0F</a>'),
'        </p>'))
,p_version_scn=>2566170
);
