,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\4F7F\7528\6B64\5C6C\6027\8F38\5165\76EE\524D\9801\9762\7684\8AAA\660E\5167\5BB9. \9801\9762\5C64\7D1A\8AAA\660E\53EF\4EE5\4F7F\7528\4EE5\4E0B\8A9E\6CD5\4F86\652F\63F4\6377\5F91:</p>'),
'<pre>"SHORTCUT_NAME"</pre>',
unistr('<p>\9810\8A2D\4E0D\6703\986F\793A\9801\9762\8AAA\660E\6587\5B57. \4E0D\904E, \60A8\53EF\4EE5\5FEB\901F\5730\958B\767C\8AAA\660E\7CFB\7D71\4F86\986F\793A\6B64\6587\5B57.</p>')))
