wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(119378956854667096)
,p_name=>'PE.PROPERTY.HELP_TEXT_CLOB.COMPONENT_PROPERTY.PAGE.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\8AAA\660E\6587\5B57\5728\63D0\4F9B\984D\5916\8CC7\8A0A\8207\5F15\5C0E\7D66\4F7F\7528\8005\65B9\9762\626E\6F14\4E86\91CD\8981\7684\89D2\8272, \7279\5225\662F\5C0D\65BC\8207\4ECB\9762\4E92\52D5\6642\9700\8981\5354\52A9\6216\8AAA\660E\7684\4F7F\7528\8005. \85C9\7531\78BA\4FDD\8AAA\660E\6587\5B57\53EF\4F9B\5B58\53D6\4E14\6709\6548\50B3\9054\5176\76EE\7684, \4FBF\53EF\63D0\6607\61C9\7528\7A0B\5F0F\7684\53EF\4F7F\7528\6027\8207\5305\5BB9\6027.</p>'),
unistr('<strong>\6700\4F73\505A\6CD5:</strong>'),
'<ol>',
unistr('<li><strong>\6E05\6670\4E14\7C21\6F54:</strong> \8AAA\660E\6587\5B57\6E05\6670\4E14\7C21\6F54, \6709\52A9\65BC\8B93\6240\6709\4F7F\7528\8005\6613\65BC\77AD\89E3. \8ACB\907F\514D\904E\5EA6\4F7F\7528\53EF\80FD\6703\5C0E\81F4\90E8\5206\4F7F\7528\8005\6DF7\6DC6\7684\6280\8853\6027\8A9E\8A00\6216\8853\8A9E.</li>'),
unistr('<li><strong>\76F8\95DC\5167\5BB9\6307\5F15:</strong> \63D0\4F9B\5167\5BB9\4E0A\8207\76F8\95DC\806F\5DE5\4F5C\6216\5143\7D20\6709\95DC\7684\8AAA\660E\6587\5B57. \9019\6709\52A9\65BC\4F7F\7528\8005\77AD\89E3\5982\4F55\5B8C\6210\7279\5B9A\52D5\4F5C, \6216\6709\6548\5730\700F\89BD\4ECB\9762.</li>'),
unistr('<li><strong>\611F\5B98\7279\5FB5:</strong> \78BA\4FDD\900F\904E\8AAA\660E\63D0\4F9B\7684\6307\793A\4E0D\5B8C\5168\4EF0\8CF4\9801\9762\5143\7D20\7684\611F\5B98\7279\5FB5 (\4F8B\5982\5F62\72C0\3001\8272\5F69\3001\5927\5C0F\6216\8996\89BA\4F4D\7F6E). \4F8B\5982, \8AAA\660E\6587\5B57\82E5\70BA\300C\6309\4E00\4E0B\9801\9762\53F3\4E0A\65B9\7684\300C\4E0B\4E00\6B65\300D\6309\9215\300D, \6703\6BD4\300C\6309\4E00\4E0B\9801\9762\53F3\4E0A\65B9\7684\6309\9215\300D\66F4\597D (\5982\6B64\6307\793A\4FBF\4E0D\6703\53EA\6709\63D0\53CA\4F4D\7F6E).</li>'),
'</ol>'))
,p_version_scn=>2566088
);
