 p_id=>wwv_flow_imp.id(119383809645667097)
,p_name=>'PE.PROPERTY.IMAGE_ALT_ATTRIBUTE.COMPONENT_PROPERTY.CLASSIC_NAV_BAR.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\66FF\4EE3\6587\5B57\662F\589E\5F37\8996\89BA\969C\7919\4F7F\7528\8005\8F14\52A9\529F\80FD\7684\91CD\8981\5143\7D20. \5B83\63D0\4F9B\6587\4EF6\6216\7DB2\9801\5167\5F71\50CF\7684\6587\5B57\63CF\8FF0, \4F9B\6DF1\5165\77AD\89E3\5B83\5011\5C0D\65BC\5167\5BB9\7684\91CD\8981\6027.</p>'),
unistr('<strong>\6700\4F73\505A\6CD5:</strong>'),
'<ol>',
unistr('<li>\6709\76EE\7684\7684\63CF\8FF0:'),
'<ul>',
unistr('<li>\66FF\4EE3\6587\5B57\61C9\7C21\6F54\5730\50B3\9054\8A72\5F71\50CF\5C0D\65BC\5468\570D\5167\5BB9\7684\91CD\8981\6027.</li>'),
unistr('<li>\61C9\8457\91CD\65BC\63CF\8FF0\300C\70BA\4F55\300D\6703\6709\6B64\5F71\50CF, \800C\4E0D\662F\8AAA\660E\5F71\50CF\662F\4EC0\9EBC.</li>'),
unistr('<li>\66FF\4EE3\6587\5B57\61C9\8A72\6E05\695A\3001\7C21\6F54\4E14\5177\63CF\8FF0\6027.</li>'),
'</ul>',
'</li>',
unistr('<strong>\7BC4\4F8B:</strong>'),
unistr('<p>"\5728\9806\5229\5B8C\6210\5177\6709\6311\6230\6027\7684\5C08\6848\5F8C, \5718\968A\4E92\76F8\64CA\638C\6176\795D\4E26\5FAE\7B11."</p>'),
unistr('\5728\672C\7BC4\4F8B\4E2D, \66FF\4EE3\6587\5B57\5F37\8ABF\5F71\50CF\80CC\5F8C\7684\539F\56E0, \5373\9806\5229\5B8C\6210\5177\6709\6311\6230\6027\7684\5C08\6848\4EE5\53CA\5718\968A\6210\54E1\4E4B\9593\7684\6176\795D. \6B64\63CF\8FF0\70BA\7121\6CD5\76F4\63A5\770B\5230\5F71\50CF\7684\4F7F\7528\8005\63D0\4F9B\80CC\666F\8CC7\8A0A, \4E26\6DF1\5165\77AD\89E3\5F71\50CF\7684\91CD\8981\610F\7FA9.'),
unistr('<li>\8CC7\8A0A\8C50\5BCC\7684\5F71\50CF:'),
unistr('\8B58\5225\5C0D\65BC\7406\89E3\6216\7DB2\9801\4E0A\4E0B\6587\6709\6240\5E6B\52A9\7684\5F71\50CF.'),
unistr('\5982\679C\79FB\9664\8A72\5F71\50CF\53EF\80FD\6703\6E1B\5C11\9801\9762\7684\610F\7FA9\6216\91CD\8981\6027, \5247\9700\6709\66FF\4EE3\6587\5B57.</li>'),
unistr('<li>\907F\514D\591A\9918\5167\5BB9:'),
unistr('\8ACB\7701\7565 "image of" \4E4B\985E\7684\8A5E\8A9E, \56E0\70BA\87A2\5E55\52A9\8B80\7A0B\5F0F\6703\81EA\52D5\6717\8AA6\6B64\70BA\5F71\50CF.</li>'),
'</ol>'))
,p_version_scn=>2566088
);
