unistr('  <dt>\5831\8868\9078\53D6\6E05\55AE</dt>'),
unistr('    <dd>\986F\793A\4F7F\7528\8005\6240\6709\53EF\7528\5831\8868\7684\6E05\55AE, \5305\62EC\4E3B\8981\3001\66FF\4EE3\3001\516C\7528\53CA\5C08\7528\5831\8868. \53EA\6709\7576\4F7F\7528\8005\53EF\4EE5\5B58\53D6\4E3B\8981\5831\8868\4EE5\5916\7684\5831\8868\6642, \624D\6703\986F\793A\6B64\6E05\55AE.</dd>'),
