wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(120835945595667569)
,p_name=>'PE.PROPERTY.INIT_POSITION_ZOOM_SOURCE_SQL.EXAMPLES'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\4EE5\4E0B\67E5\8A62\50B3\56DE NUMBER \8CC7\6599\6B04\4EE5\6C7A\5B9A\8D77\59CB\5730\5716\4F4D\7F6E\548C\7E2E\653E\7B49\7D1A:</p>'),
'<pre>',
'select -133.5 longitude,',
'         35.2 latitude,',
'            3 zoom',
'  from sys.dual',
'</pre>',
unistr('<p>\4EE5\4E0B\67E5\8A62\50B3\56DE SDO_GEOMETRY \8CC7\6599\6B04\4EE5\6C7A\5B9A\8D77\59CB\5730\5716\4F4D\7F6E, \50B3\56DE NUMBER \8CC7\6599\6B04\4EE5\6C7A\5B9A\7E2E\653E\7B49\7D1A.</p>'),
'<pre>',
'select sdo_geometry( 2001,                                 -- 2 dimensional point',
'                     4326,                                 -- longitude/latitude (WGS84)',
'                     sdo_point_type( -133.5, 35.2, null ), -- concrete coordinates',
'                     null,                                 -- not used for points',
'                     null                                  -- not used for points',
'       )                   as geometry,',
'       3                   as zoom',
'  from sys.dual',
'</pre>'))
,p_version_scn=>2566311
