,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\8F38\5165\6B64\9801\9762\7684 CSS \7A0B\5F0F\78BC. \5728\6B64\8F38\5165\7684\4EFB\4F55 CSS \53EA\6703\5957\7528\81F3\6B64\9801\9762, \4E0D\6703\5F71\97FF\4EFB\4F55\5176\4ED6\9801\9762. \8F38\5165\7684 CSS \7A0B\5F0F\78BC\5C07\6703\53D6\4EE3\9801\9762\6A23\677F\4E2D\7684 #PAGE_CSS# \66FF\4EE3\5B57\4E32.</p>'),
unistr('<p>\82E5\591A\500B\9801\9762\9700\8981\76F8\540C\7684 CSS, \6700\597D\5C07\7A0B\5F0F\78BC\653E\5165\5916\90E8\6A94\6848. \9019\6A23\6709\52A9\65BC\907F\514D\91CD\8907, \9084\53EF\5229\7528\700F\89BD\5668\975C\614B\6A94\6848\5FEB\53D6. \60A8\53EF\4EE5\524D\5F80\300C\5171\7528\7684\5143\4EF6\300D>\300C\4F7F\7528\8005\4ECB\9762\5C6C\6027\300D>\300CCSS\300D>\300C\6A94\6848 URL\300D, \5728\61C9\7528\7A0B\5F0F\5C64\7D1A\53C3\7167\5916\90E8\6A94\6848.</p>'),
unistr('<p>\8ACB\6CE8\610F, \60A8\4E0D\9700\8981\5305\62EC\958B\982D\548C\7D50\5C3E <code>style</code> \6A19\8A18. \53EA\8981\65B0\589E CSS \7A0B\5F0F\78BC\5373\53EF.</p>')))
,p_version_scn=>2566169
);
