'<ol>',
unistr('<li><strong>\4F7F\7528\9BAE\660E\4E14\6E05\6670\7684\8272\5F69:</strong> \9078\64C7\4F7F\7528\9BAE\660E\4E14\6E05\6670\7684\8272\5F69\53EF\78BA\4FDD\80FD\5920\8F15\6613\5730\8FA8\8B58\5716\8868\5167\7684\6587\5B57\548C\5716\5F62\5143\7D20. \9019\53EF\63D0\6607\6240\6709\4F7F\7528\8005\7684\53EF\95B1\8B80\6027\548C\7406\89E3, \5305\62EC\8996\89BA\969C\7919\4F7F\7528\8005.</li>'),
unistr('<li><strong>\6AA2\67E5\8272\5F69\5C0D\6BD4\5EA6:</strong> \4F7F\7528\5C0D\6BD4\5EA6\6AA2\67E5\5DE5\5177\8A55\4F30\524D\666F\8207\80CC\666F\8272\5F69\4E4B\9593\7684\8272\5F69\5C0D\6BD4\5EA6. \76EE\6A19\5C0D\6BD4\5EA6\81F3\5C11\9700\70BA 4.5:1, \4EE5\78BA\4FDD\4E0D\540C\8996\89BA\969C\7919\7A0B\5EA6\4E4B\4F7F\7528\8005\7684\53EF\95B1\8B80\6027.</li>'),
'</ol>'))
,p_version_scn=>2566088
);
