unistr('<p>\8F38\5165\7528\65BC\986F\793A\72C0\614B\8A08\91CF\91CF\8868\5716\7E6A\5716\5340\7684\8272\5F69. \60A8\53EF\4EE5\4F7F\7528 <code>&COLUMN_VALUE.</code> \66FF\4EE3\9805\76EE. \5716\8868\5C1A\672A\5B9A\7FA9\81E8\754C\503C\8272\5F69\6642\624D\6703\5957\7528\6B64\8272\5F69.</p>'),
unistr('<p>\8272\5F69\4F7F\7528\5341\516D\9032\4F4D (hex) \8868\793A\6CD5\3001RGB \8272\5F69\4EE3\78BC\6216 HTML \8272\5F69\540D\7A31\6307\5B9A. \5341\516D\9032\4F4D\8868\793A\6CD5\5B9A\7FA9\70BA #xxyyzz (# \5F8C\9762\63A5\8457 3 \7D44\96D9\4F4D\6578\7684\5341\516D\9032\4F4D\6578\5B57), \5176\4E2D xx\3001yy \548C zz \70BA\5169\500B\5B57\5143\7684\5341\516D\9032\4F4D\503C, \5206\5225\4EE3\8868\7D05\8272\3001\7DA0\8272\548C\85CD\8272.'),
unistr('RGB \4EE3\78BC\5B9A\7FA9\70BA RGB(xxx,xxx,xxx), \5176\4E2D xxx \662F 0 \5230 255 \4E4B\9593\7684\6578\5B57, \5404\81EA\70BA\4E00\500B 8 \4F4D\5143\7684\4F4D\5143\7D44\503C, \5206\5225\4EE3\8868\7D05\8272\3001\7DA0\8272\548C\85CD\8272.</p>'),
unistr('<p>\8ACB\5F9E\7DB2\969B\7DB2\8DEF\641C\5C0B\300CHTML \8272\5F69\4EE3\78BC\300D, \5C0B\627E\60F3\4F7F\7528\4E4B\8272\5F69\7684\540C\7B49\5341\516D\9032\4F4D\4EE3\78BC\6216 RGB \4EE3\78BC.</p>')))
