'<dd><pre>/myjs/#MIN_DIRECTORY#main#MIN#.js</pre></dd>',
unistr('<dt>\5982\679C\4E5F\6703\900F\904E RequireJS require \547C\53EB\4F7F\7528\7A0B\5F0F\5EAB, \8ACB\4F7F\7528\6B64\8A9E\6CD5. define \540D\7A31\5FC5\9808\8207 requirejs.config \8DEF\5F91\4E2D\4F7F\7528\7684\76F8\540C, \800C\503C\5FC5\9808\662F\7A0B\5F0F\5EAB\986F\793A\7684\5168\57DF\7B26\865F. \9019\53EA\6709\5728\4F7F\7528 RequireJS \6642\9069\7528. \5982\6B64\53EF\907F\514D RequireJS \91CD\65B0\8F09\5165\8A72\7A0B\5F0F\5EAB.</dt>'),
'<dd><pre>[define hammerjs=Hammer]/myjs/hammer.js</pre></dd>',
unistr('<dt>\5982\679C\6A94\6848\76F8\4F9D\65BC RequireJS, \8ACB\4F7F\7528\6B64\8A9E\6CD5. \9019\6703\81EA\52D5\65BC\6B64\6A94\6848\4E4B\524D\5148\884C\8F09\5165 RequireJS.</dt>'),
'<dd><pre>[require requirejs]/myjs/main.js</pre></dd>',
unistr('<dt>\5982\679C\6A94\6848\76F8\4F9D\65BC Oracle JET, \8ACB\4F7F\7528\6B64\8A9E\6CD5. \9019\6703\81EA\52D5\65BC\6B64\6A94\6848\4E4B\524D\5148\884C\8F09\5165 RequireJS \548C Oracle JET RequireJS \7D44\614B.</dt>'),
'<dd><pre>[require jet]/myjs/main.js</pre></dd>',
unistr('<dt>\5982\679C\6A94\6848\662F JavaScript ES \6A21\7D44, \8ACB\4F7F\7528\6B64\8A9E\6CD5. \9019\6703\5C07 <code>type="module"</code> \65B0\589E\81F3\547D\4EE4\6A94\6A19\8A18\4E2D.</dt>'),
'<dd><pre>[module]/myjs/main.js</pre></dd>',
unistr('<dt>\5982\679C\61C9\4EE5\975E\540C\6B65\65B9\5F0F\8F09\5165\6A94\6848, \8ACB\4F7F\7528\6B64\8A9E\6CD5. \9019\6703\5C07 <code>async</code> \5C6C\6027\65B0\589E\81F3\547D\4EE4\6A94\6A19\8A18\4E2D.</dt>'),
'<dd><pre>[async]/myjs/main.js</pre></dd>',
unistr('<dt>\5982\679C\6A94\6848\53EA\80FD\5728\5256\6790\6587\4EF6\5F8C\624D\57F7\884C\6A94\6848, \8ACB\4F7F\7528\6B64\8A9E\6CD5. \9019\6703\5C07 <code>defer</code> \5C6C\6027\65B0\589E\81F3\547D\4EE4\6A94\6A19\8A18\4E2D. \8ACB\6CE8\610F, \9810\8A2D\6703\5EF6\7DE9\6A21\7D44.</dt>'),
'<dd><pre>[defer]/myjs/main.js</pre></dd>',
unistr('<dt>\60A8\53EF\4EE5\63D0\4F9B\591A\500B\6A94\6848 URL \6307\4EE4, \4F46\5FC5\9808\4EE5\9017\865F\5340\9694.</dt>'),
'<dd><pre>[module, async]/myjs/main.js</pre></dd>',
unistr('<dt>\5728\53C3\7167\61C9\7528\7A0B\5F0F\7248\672C\4E4B URL \4E2D\4F7F\7528\67E5\8A62\5B57\4E32\7684\6A94\6848\53C3\7167, \5982\6B64\7576\61C9\7528\7A0B\5F0F\5347\7D1A\5F8C (\4E14\7248\672C\905E\589E), \7CFB\7D71\6703\6307\793A\700F\89BD\5668\4E00\5F8B\8F09\5165\65B0\6A94\6848, \4E26\5FFD\7565\6240\6709\5148\524D\5FEB\53D6\7684\6A94\6848.</dt>'),
