,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\6309\4E00\4E0B\300C\76EE\6A19\300D\5373\53EF\547C\53EB\5F37\5236\56DE\61C9\5C0D\8A71\65B9\584A. \60A8\53EF\4EE5\8F38\5165\9EDE\9078\300C\9023\7D50\8CC7\6599\6B04\300D\5F8C\6240\8981\547C\53EB\7684\81EA\8A02\76EE\6A19.</p>'),
unistr('        <p>\8ACB\4F9D\64DA\60A8\7684\9700\6C42, \5728\300C\9023\7D50\7522\751F\5668 - \76EE\6A19\300D\4E2D\9078\53D6\9069\7576\7684\985E\578B:'),
'        <dl>',
unistr('        <dt>\6B64\61C9\7528\7A0B\5F0F\7684\9801\9762</dt>'),
unistr('        <dd>\8ACB\8F38\5165\4E0B\5217\5404\9805:'),
'        <ul>',
unistr('        <li>\9801\9762 - \8F38\5165\8981\700F\89BD\7684\9801\78BC\6216\9801\9762\5225\540D. \60A8\4E5F\53EF\4EE5\5F9E\9078\53D6\6E05\55AE\4E2D\9078\53D6\9801\78BC.</li>'),
unistr('        <li>\8A2D\5B9A\9805\76EE: \540D\7A31 - \8F38\5165\6216\9078\53D6\8981\8A2D\5B9A\81F3\968E\6BB5\4F5C\696D\72C0\614B\7684\9801\9762\9805\76EE (<code>P3_ID</code>)\3001\61C9\7528\7A0B\5F0F\9805\76EE (<code>LAST_PAGE</code>) \6216\4E92\52D5\5F0F\5831\8868\7BE9\9078 (<code>IR_EMPNO</code>).</li>'),
unistr('        <li>\8A2D\5B9A\9805\76EE: \503C - \8F38\5165\6216\9078\53D6\5831\8868\8CC7\6599\6B04 (<code>#ID#</code>)\3001\8F38\5165\61C9\7528\7A0B\5F0F\6216\9801\9762\9805\76EE (<code>&P2_EMPNO.</code>), \6216\8005\8F38\5165\4E00\500B\975C\614B\503C (<code>2</code>).</li>'),
unistr('        <li>\6E05\9664\5FEB\53D6 - \8F38\5165\8981\6E05\9664\7684\9801\78BC (<code>2,3</code>)\3001\9805\76EE (<code>P3_EMPNO,LAST_PAGE</code>) \4EE5\53CA\5831\8868\8A2D\5B9A\503C\6E05\55AE (\4F7F\7528\9017\865F\5340\9694). \82E5\8981\91CD\8A2D\5831\8868\7684\5206\9801, \8ACB\8F38\5165 <code>RP</code>. \82E5\8981\6E05\9664\6216\91CD\8A2D\4E92\52D5\5F0F\5831\8868\8A2D\5B9A\503C, \8ACB\8F38\5165 <code>CIR</code> \6216 <code>RIR</code>.</li>'),
unistr('        <li>\91CD\8A2D\5206\9801 - \9078\53D6\300C\662F\300D\5373\53EF\91DD\5C0D\76EE\6A19\9801\9762\4E0A\7684\5831\8868, \5C07\5206\9801\91CD\8A2D\56DE\7B2C\4E00\7D44\8A18\9304. \5176\4F5C\7528\5C31\50CF\5728\300C\6E05\9664\5FEB\53D6\300D\4E2D\50B3\9001 <code>RP</code> \4E00\6A23.</li>'),
unistr('        <li>\9032\968E: \8981\6C42 - \8F38\5165\8981\4F7F\7528\7684\8981\6C42.</li>'),
'        </ul>',
'        </dd>',
unistr('        <dt>\4E0D\540C\61C9\7528\7A0B\5F0F\4E2D\7684\9801\9762</dt>'),
unistr('        <dd>\8F38\5165\8207\300C\6B64\61C9\7528\7A0B\5F0F\7684\9801\9762\300D\6240\5217\76F8\540C\7684\5C6C\6027, \53E6\5916\52A0\4E0A\300C\61C9\7528\7A0B\5F0F\300D\7684\61C9\7528\7A0B\5F0F ID \6216\61C9\7528\7A0B\5F0F\5225\540D.</dd>'),
