,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\53EF\5B58\53D6\7684\9023\7D50\6587\5B57\662F\4F7F\7528\50CF\87A2\5E55\52A9\8B80\7A0B\5F0F\7B49\8F14\52A9\6280\8853\4E4B\4F7F\7528\8005\7684\5FC5\8981\9805\76EE, \53EF\8B93\4F7F\7528\8005\66F4\6709\6548\5730\700F\89BD\8207\7406\89E3\5167\5BB9.</p>'),
unistr('<strong>\6700\4F73\505A\6CD5:</strong>'),
'<ol>',
unistr('<li><strong>\7C21\660E\627C\8981:</strong> \8B93\9023\7D50\6587\5B57\7C21\55AE\660E\77AD\4E14\540C\6642\53EF\50B3\9054\5FC5\8981\8CC7\8A0A. \76EE\6A19\70BA\5728\7C21\6F54\8207\63CF\8FF0\6027\4E4B\9593\53D6\5F97\5E73\8861.</li>'),
unistr('<li><strong>\8F14\52A9\529F\80FD\5C6C\6027:</strong> \78BA\5B9A\5DF2\5B9A\7FA9\5831\8868\8CC7\6599\6B04\8CC7\6599\5217\6A19\982D. \5B9A\7FA9\6B64\5C6C\6027\53EF\5728\5217\8868\5316\8CC7\6599\4E2D\63D0\4F9B\6E05\695A\7684\65B9\5411\9EDE, \4EE5\6539\5584\87A2\5E55\52A9\8B80\7A0B\5F0F\4F7F\7528\8005\7684\5C0E\89BD\9AD4\9A57.</li>'),
