wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(120443004239667426)
,p_name=>'PE.PROPERTY.LOST_UPDATE_CHECK_TYPE.HELP'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\9078\53D6\4FDD\8B77\8CC7\6599, \4F7F\5176\4E0D\81F3\65BC\767C\751F\907A\5931\66F4\65B0\7684\65B9\5F0F.'),
unistr('		\7576\5169\4F4D\6216\66F4\591A\4F4D\4F7F\7528\8005\5617\8A66\66F4\65B0\76F8\540C\8CC7\6599\6642\5C31\6703\767C\751F\907A\5931\66F4\65B0, \800C\4E14\6700\5F8C\7684\66F4\65B0\6703\8986\5BEB\7B2C\4E00\4F4D\4F7F\7528\8005\6240\505A\7684\66F4\65B0\4EE5\5132\5B58\8B8A\66F4.'),
unistr('		\70BA\907F\514D\767C\751F\9019\7A2E\60C5\6CC1, \66F4\65B0\53EF\4EE5\6AA2\67E5\8CC7\6599\5EAB\4E2D\73FE\6709\7684\8CC7\6599\6B04\503C\8207\539F\5148\67E5\8A62\8A18\9304\6642\6240\64F7\53D6\7684\503C.</p>'),
unistr('		<p>\4F8B\5982:'),
'          <ol>',
unistr('            <li>\4F7F\7528\8005 A \67E5\8A62\54E1\5DE5 (EMP) \8A18\9304.</li>'),
unistr('		    <li>\4F7F\7528\8005 B \67E5\8A62\76F8\540C\7684\54E1\5DE5\8A18\9304.</li>'),
unistr('		    <li>\4F7F\7528\8005 B \66F4\65B0 EMPNO = 7839 \7684\54E1\5DE5\8A73\7D30\8CC7\8A0A, \4E26\5C07\8B8A\66F4\5957\7528 (\78BA\8A8D) \81F3\8CC7\6599\5EAB.</li>'),
unistr('		    <li>\4F7F\7528\8005 A \66F4\65B0 EMPNO = 7839 \7684\54E1\5DE5\8A73\7D30\8CC7\8A0A, \4E26\5617\8A66\5C07\8B8A\66F4\5957\7528\81F3\8CC7\6599\5EAB.</li>'),
'          </ol>',
unistr('          \5982\679C\4F7F\7528\8005 A \9806\5229\66F4\65B0\76F8\540C\7684\8A18\9304, \4F7F\7528\8005 B \6240\505A\7684\8B8A\66F4\5C31\6703\907A\5931.</p>'),
unistr('         <p>\7576\4F7F\7528\8005 A \5617\8A66\5132\5B58\8A72\54E1\5DE5\8A18\9304\6642, \8CC7\6599\5EAB\4E2D\7684\8CC7\6599\6703\8207\4F7F\7528\8005 A \539F\5148\67E5\8A62\7684\8CC7\6599\4E0D\540C.'),
unistr('		  \5728\4EE5\4E0A\7684\6B65\9A5F 1 \4E2D, \53EF\4EE5\64F7\53D6\4F7F\7528\8005 A \539F\5148\67E5\8A62\7684\8CC7\6599\6B04\503C.'),
unistr('		  \63A5\8457\5728\4EE5\4E0A\7684\6B65\9A5F 4 \4E2D, \53EF\4EE5\5C07\503C\8207\8CC7\6599\5EAB\4E2D\76EE\524D\7684\503C\505A\6BD4\8F03.'),
unistr('		  \7531\65BC\4F7F\7528\8005 B \5728\6B65\9A5F 3 \66F4\65B0\4E86\8CC7\6599\5EAB\503C, \56E0\6B64\9019\9805\6BD4\8F03\6703\5F15\767C\4F7F\7528\8005 A \7684\932F\8AA4.'),
unistr('		  \9019\6703\8B93\4E00\4F4D\4F7F\7528\8005\7121\6CD5\8986\5BEB\53E6\4E00\4F4D\4F7F\7528\8005\5C0D\76F8\540C\8CC7\6599\5217\6240\505A\7684\8B8A\66F4.</p>'),
unistr('		  <p>\6CE8\610F - \552F\6709\5728\76F8\5C0D\61C9\7684\8655\7406\4F5C\696D (\4E92\52D5\5F0F\65B9\683C - \81EA\52D5\8CC7\6599\5217\8655\7406 (DML)) \555F\7528<strong>\9632\6B62\907A\5931\66F4\65B0</strong>\6642, \624D\6703\4F7F\7528\300C\907A\5931\66F4\65B0\985E\578B\300D.</p>')))
,p_version_scn=>2566246
);
