,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\78BA\5B9A\9EDE\53E2\96C6\586B\5165\7684\8272\5F69\6EFF\8DB3\7279\5B9A\689D\4EF6, \4EE5\63D0\6607\6240\6709\4F7F\7528\8005\7684\53EF\898B\6027\548C\53EF\7528\6027.</p>'),
unistr('<strong>\6700\4F73\505A\6CD5:</strong><ol>'),
unistr('<li><strong>\5C0D\6BD4\5EA6:</strong> \9EDE\53E2\96C6\586B\5165\8207\5176\80CC\666F\7684\5C0D\6BD4\5EA6\81F3\5C11\5FC5\9808\70BA (3:1). \9019\6A23\53EF\78BA\4FDD\6709\8996\529B\969C\7919\7684\4F7F\7528\8005\80FD\5920\6709\6548\5730\5206\8FA8\53E2\96C6\9EDE.</li>'),
unistr('<li><strong>\8207\6A19\6E96\586B\5165\8272\5F69\6709\6240\5340\5206:</strong> \9EDE\53E2\96C6\586B\5165\8272\5F69\4E5F\5FC5\9808\8207\6A19\6E96\586B\5165\8272\5F69\6709\6240\5340\5225. \6B64\5DEE\7570\5F88\91CD\8981, \5982\6B64\624D\80FD\8B93\4F7F\7528\8005\8F15\9B06\5206\8FA8\53E2\96C6\9EDE\548C\6A19\6E96\8CC7\6599\9EDE, \4EE5\589E\5F37\5C0D\8CC7\6599\7684\7406\89E3\548C\4E92\52D5.</li>'),
'</ol>',
unistr('<p>\85C9\7531\9075\5B88\9019\4E9B\6E96\5247, \7121\8AD6\4F7F\7528\8005\7684\8996\89BA\80FD\529B\70BA\4F55, \90FD\53EF\70BA\4ED6\5011\5EFA\7ACB\66F4\591A\5143\4E14\6613\65BC\4F7F\7528\7684\9AD4\9A57.</p>')))
,p_version_scn=>2566088
);
