wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(120843233364667571)
,p_name=>'PE.PROPERTY.MAP_REGION_STATUS_ITEM.HELP'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\5982\679C\9078\64C7\4E86\67D0\500B\9801\9762\9805\76EE, \5730\5716\5340\57DF\4E00\5F8B\6703\4EE5\6B64\9805\76EE\7684\503C\8207 GeoJSON \683C\5F0F\7DAD\6301\4F4F\76EE\524D\7684\5730\5716\5B9A\754C\6846. \9019\5C0D\65BC\5C07\5730\5716\9023\63A5\81F3\5176\4ED6 APEX \5143\4EF6 (\4F8B\5982, \4E00\822C\5831\8868\6216\4E92\52D5\5F0F\5831\8868) \975E\5E38\5BE6\7528: \5176\4ED6\5143\4EF6\53EF\4EE5\4F7F\7528\5B9A\754C\6846\9805\76EE\7684\5167\5BB9\4F86\57F7\884C\7A7A\9593\67E5\8A62, \4EE5\53CA\986F\793A\53EA\5728\5730\5716\4E0A\53EF\898B\7684\8CC7\6599.</p>'),
unistr('<p>\4E00\4E9B\5730\5716\79FB\52D5\6216\7E2E\653E\7B49\7D1A\8B8A\66F4\5F8C\7684\5B9A\754C\6846\9805\76EE\5167\5BB9\7BC4\4F8B:</p>'),
'<pre>',
'{',
'  "type": "Polygon",',
'  "coordinates": [[',
'                    [-5.499,46.380],',
'                    [ 8.187,46.380],',
'                    [ 8.187,49.550],',
'                    [-5.499,49.550],',
'                    [-5.499,46.380]]]',
'}',
'</pre>',
'<p>',
unistr('\82E5\8981\5C07\5730\5716\9023\63A5\81F3\5831\8868\5340\57DF, \53EF\4F7F\7528<strong>\91CD\65B0\6574\7406</strong>\52D5\614B\52D5\4F5C. \53EF\4EE5\5C0D\5831\8868\5340\57DF\5957\7528\7A7A\9593\7BE9\9078\689D\4EF6, \4EE5\53EA\986F\793A\5730\5716\4E0A\4E5F\53EF\898B\7684\7D50\679C.</p>'),
unistr('<p>\5831\8868\67E5\8A62\7BC4\4F8B:</p>'),
'<pre>',
'select [column1],',
'       [column2],',
'       ...',
'  from ...',
' where sdo_anyinteract(',
'           [geometry-column],',
'           sdo_util.from_geojson( :[item-name-of-bounding-box-item] )',
'       ) = ''TRUE''',
'   and ...',
'</pre>'))
,p_version_scn=>2566313
);
