wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(120304263892667382)
,p_name=>'PE.PROPERTY.OPTIMIZER_HINT.EXAMPLES'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'<dt><pre>INDEX (employees emp_department_ix)</pre></dt>',
unistr('<dd>\82E5\8981\5B58\53D6 <code>employee</code> \8868\683C, \8ACB\5617\8A66\4F7F\7528 <code>emp_department_ix</code> \7D22\5F15</dd>'),
'<dt><pre>WITH_PLSQL</pre></dt>',
unistr('<dd>\5728 SQL \67E5\8A62\5167\555F\7528 <code>WITH plsql_declarations</code> \5B50\53E5\7684\4F7F\7528</dd>'),
'</dl>',
unistr('<h5>\60A8\53EF\4EE5\4F7F\7528\4E0B\5217 <em>APEX \865B\64EC\63D0\793A</em>:</h5>'),
'<dl>',
'<dt><pre>APEX$USE_OFFSET_PAGINATION</pre></dt>',
unistr('<dd>\7522\751F\5206\9801 SQL \6642, \6539\7528 <strong>OFFSET m ROWS FETCH n ROWS</strong> (SQL2008) \8A9E\6CD5, \800C\975E <strong>ROW_NUMBER</strong> \5206\6790\51FD\6578. \57F7\884C\7684\67E5\8A62\5C07\53EA\6703\50B3\56DE\76EE\524D\5143\4EF6\9801\9762\6240\9700\7684\8CC7\6599\5217.</dd>'),
'<dt><pre>APEX$USE_ROWNUM_PAGINATION</pre></dt>',
unistr('<dd>\7522\751F\5206\9801 SQL \6642, \6539\7528 <strong>ROWNUM</strong> \865B\64EC\8CC7\6599\6B04, \800C\975E <strong>ROW_NUMBER</strong> \5206\6790\51FD\6578. \57F7\884C\7684\67E5\8A62\5C07\53EA\6703\50B3\56DE\76EE\524D\5143\4EF6\9801\9762\6240\9700\7684\8CC7\6599\5217.</dd>'),
'<dt><pre>APEX$USE_NO_PAGINATION</pre></dt>',
unistr('<dd>\4E0D\5EFA\7ACB\4EFB\4F55\5206\9801 SQL. \5143\4EF6\4E00\5F8B\6703\5F9E\7B2C\4E00\5217\958B\59CB\64F7\53D6; \6703\85C9\7531\7565\904E\8CC7\6599\5217, \4E26\4E14\5728\64F7\53D6\6240\9700\7684\6700\5F8C\4E00\5217\4E4B\5F8C\505C\6B62\7684\65B9\5F0F\986F\793A\76EE\524D\7684\9801\9762.</dd>'),
'<dt><pre>APEX$USE_NO_BULK_FETCH</pre></dt>',
unistr('<dd>\4E0D\5C0D\6B64\67E5\8A62\4F7F\7528\5927\91CF\64F7\53D6.</dd>'),
'<dt><pre>APEX$USE_NO_GROUPING_SETS</pre></dt>',
unistr('<dd>\8ACB\52FF\5728\591A\9762\5411\641C\5C0B\6216\667A\6167\578B\7BE9\9078\689D\4EF6\4F7F\7528 <strong>GROUPING SETS</strong> SQL \5B50\53E5. \8ACB\6539\7528\500B\5225\67E5\8A62\8A08\7B97\6BCF\500B\9762\5411\6216\7BE9\9078\689D\4EF6\7684\6578\76EE, \4E26\4F7F\7528 UNION ALL \5C07\5176\7D50\5408\8D77\4F86.</dd>'),
'</dl>'))
,p_version_scn=>2566216
);
