,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\9078\53D6\8981\70BA\9019\500B\9A57\8B49\6E2C\8A66\7684\76F8\7B49\985E\578B. \4F9D\64DA\60A8\7684\9078\64C7\9805\76EE\800C\5B9A, \53EF\80FD\9700\8981\4E00\6216\591A\500B\5176\4ED6\5C6C\6027, \624D\80FD\5B8C\6574\5B9A\7FA9\9019\500B\9A57\8B49.</p>'),
unistr('<p>\5982\679C\9A57\8B49\901A\904E\76F8\7B49\6E2C\8A66, \6216\8A55\4F30\70BA TRUE, \5C07\4E0D\6703\986F\793A\9A57\8B49\932F\8AA4\8A0A\606F.'),
unistr('\5982\679C\9A57\8B49\672A\901A\904E\76F8\7B49\6E2C\8A66\3001\8A55\4F30\70BA FALSE \6216\50B3\56DE\975E\7A7A\767D\7684\6587\5B57\5B57\4E32, \5C31\6703\986F\793A\9A57\8B49\932F\8AA4\8A0A\606F.</p>'),
unistr('<p>\9A57\8B49\5931\6557\4E26\4E0D\6703\5C0E\81F4\505C\6B62\5F8C\7E8C\7684\9A57\8B49\8A55\4F30, \56E0\6B64\6BCF\500B\5F8C\7E8C\7684\9A57\8B49\53EF\80FD\6703\5F15\767C\5176\4ED6\7684\9A57\8B49\932F\8AA4\8A0A\606F. \5982\679C\60A8\60F3\8981\505C\6B62\57F7\884C\5F8C\7E8C\7684\9A57\8B49, \5C31\5FC5\9808\5C07\5176\4ED6\908F\8F2F\52A0\5230\7B2C\4E00\500B\5931\6557\7684\9A57\8B49\4E2D (\4F8B\5982\5C07\67D0\500B\9801\9762\9805\76EE\8A2D\6210\7279\5B9A\503C), \7136\5F8C\8996\9700\8981\5728\5F8C\7E8C\7684\9A57\8B49\4E0A\589E\5F37\689D\4EF6\6027\908F\8F2F. \5982\679C\4E00\6216\591A\500B\9A57\8B49\672A\901A\904E\8A55\4F30, \5C07\4E0D\6703\57F7\884C\5F8C\7E8C\7684\8655\7406\4F5C\696D\548C\5206\652F.</p>')))
,p_version_scn=>2566284
);
