,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p><p>\8F38\5165\5831\8868\5BB9\5668\6A23\677F\7684 HTML \6A19\8A18. \53EF\4F7F\7528 <code>#STATIC_ID#</code> \8A9E\6CD5\53C3\7167\300C\5831\8868\300D\7BC4\570D\81EA\8A02\5C6C\6027\7684\975C\614B ID.'),
unistr('\60A8\53EF\4EE5\4F7F\7528<strong>\540C\6B65\5C6C\6027</strong>\6309\9215, \5FEB\901F\540C\6B65\6240\6709\7684\81EA\8A02\5C6C\6027\9810\7559\4F4D\7F6E.'),
