unistr('<dd>\70BA\5340\57DF\6307\5B9A\7684 CSS \985E\5225.</dd>'),
'<dt>APEX$REPORT_BODY</dt>',
unistr('<dd>\300C\5831\8868\672C\6587\300D\6A23\677F\7684\8F38\51FA.</dd>'),
'</dl>',
'</p>',
unistr('<p>\60A8\4E5F\53EF\4EE5\4F7F\7528\4F4D\7F6E\9810\7559\4F4D\7F6E, \8B93\6B64\5831\8868\5BB9\5668\80FD\5920\5448\73FE\9801\9762\5143\4EF6 (\5340\57DF\3001\9805\76EE\3001\6309\9215).<br /> \53EF\4F7F\7528 <code>#SLOT_STATIC_ID#</code> \8A9E\6CD5\53C3\7167\4F4D\7F6E.<br />'),
unistr('\82E5\8981\4F9D\64DA\4F4D\7F6E\4F7F\7528\72C0\6CC1\6709\689D\4EF6\5730\5448\73FE\4F4D\7F6E, \8ACB\4F7F\7528 <code>{if SLOT_STATIC_ID/}&lt;div class="inner-div"&gt;#SLOT_STATIC_ID#&lt;/div&gt;{endif/}</code> \8A9E\6CD5, \53EA\5728\4F7F\7528\4F4D\7F6E\6642\624D\5448\73FE\5176\4ED6\6A19\8A18.<br />'),
