,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\8ACB\9078\53D6\4E00\500B\4F9B\7528\65BC\5B9A\7FA9\6B64\4E00\822C\5831\8868\4E4B\5916\89C0\548C\7248\9762\914D\7F6E\7684\5831\8868\6A23\677F.</p>'),
unistr('        <p>\5831\8868\6A23\677F\5B9A\7FA9\65BC\61C9\7528\7A0B\5F0F\4E3B\984C\4E2D.'),
unistr('        \4E00\822C\5831\8868\5EFA\7ACB\4E4B\5F8C, \5C31\6703\81EA\52D5\5C07\6B64\6A23\677F\8A2D\70BA\76EE\524D\4E3B\984C\4E2D\5B9A\7FA9\7684\9810\8A2D\5831\8868\6A23\677F.</p>'),
unistr('        <p>\8A31\591A\4E3B\984C\90FD\5305\542B\4E00\822C\5831\8868\6A23\677F, \53EF\7528\65BC\4EE5\8868\683C\3001\7D22\5F15\9375\503C\7D44\3001\641C\5C0B\7D50\679C\3001\5361\7247\7B49\65B9\5F0F\986F\793A\8CC7\6599.'),
unistr('        \8ACB\6CE8\610F, \67D0\4E9B\5831\8868\6A23\677F (\4F8B\5982\5361\548C\641C\5C0B\7D50\679C) \662F\300C\4EE5\8CC7\6599\5217\70BA\57FA\790E\300D, \56E0\6B64\60A8\7684 SQL \67E5\8A62\61C9\8A72\50B3\56DE\6A23\677F\4E2D\66FF\4EE3\7684\4E00\7D44\7279\5B9A\8CC7\6599\6B04\5225\540D.<br>'),
unistr('        \300C\901A\7528\4E3B\984C\300D\63D0\4F9B\4E0B\5217\5831\8868\6A23\677F:'),
'          <dl>',
unistr('            <dt>\8B66\793A</dt>'),
unistr('              <dd>\5728\60A8\7684\9801\9762\4E2D\986F\793A\4EFB\610F\6578\76EE\7684\6C34\5E73\8B66\793A\6216\901A\77E5.</dd>'),
unistr('            <dt>\6A19\8A18\6E05\55AE</dt>'),
unistr('              <dd>\4EE5\985E\4F3C\5100\8868\677F\7684\4F7F\7528\8005\4ECB\9762\986F\793A\7D22\5F15\9375\503C\7D44.</dd>'),
unistr('            <dt>\5361\7247</dt>'),
unistr('              <dd>\4EE5\5361\7247\6216\5C0F\578B\5340\584A\65B9\5F0F\986F\793A\5831\8868\8CC7\6599, \9069\7528\65BC\5448\73FE\5404\7A2E\4E0D\540C\7684\8CC7\8A0A. \5361\7247\53EF\4EE5\900F\904E\300C\6A23\677F\9078\9805\300D\9032\884C\5927\5E45\81EA\8A02.</dd>'),
unistr('            <dt>\8A3B\89E3</dt>'),
unistr('              <dd>\986F\793A\8A3B\89E3\548C\5176\4ED6\8A0A\606F.</dd>'),
unistr('            <dt>\5167\5BB9\8CC7\6599\5217</dt>'),
unistr('              <dd>\5728\4E00\7D44\8CC7\6599\5217\986F\793A\5831\8868\8CC7\6599, \9084\652F\63F4\9078\53D6\9805\76EE\8CC7\6599\6B04\3001\5716\793A\548C\52D5\4F5C. \9069\7528\65BC\5927\90E8\5206\7684\5167\5BB9\985E\578B.</dd>'),
unistr('            <dt>\76F8\95DC\8CC7\8A0A\74B0\5883\8CC7\8A0A</dt>'),
