,p_name=>'PE.PROPERTY.SHORTCUT_PLSQL_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>\54E1\5DE5\82E5\7DE8\5236\5728\90E8\9580 30 \5247\50B3\56DE YES:</dt>'),
'<dd><pre>',
'declare',
'    l_deptno number;',
'begin',
'    select deptno',
'      into l_deptno',
'      from emp',
'     where empno = :P2_EMPNO;',
'',
'    if l_deptno = 30 then',
'        return ''YES'';',
'    else',
'        return ''NO'';',
'    end if;',
'end;',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2566208
);
