,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>\5217\5370\6240\6709\54E1\5DE5\540D\7A31\53CA\5176\5DE5\4F5C\7684\6E05\55AE:</dt>'),
'<dd><pre>',
'declare',
'    l_result clob := ''&lt;h4>List of employees:&lt;/h4&gt;'';',
'begin',
'    l_result := l_result || ''&lt;ul&gt;'';',
'    for l_emp in ( select ename,',
'                          job',
'                     from emp',
'                    order by ename )',
'    loop',
'        l_result := l_result ||',
'                    ''&lt;li&gt;&lt;strong&gt;'' || apex_escape.html( l_emp.ename ) || ''&lt;/strong&gt;'' ||',
'                    '' ('' || apex_escape.html( l_emp.job ) || '')&lt;/li&gt;'';',
'    end loop;',
'    l_result := l_result || ''&lt;/ul&gt;'';',
'',
'    return l_result;',
'end;',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2566209
);
