,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\9801\9762\6A19\984C\5C0D\65BC\5354\52A9\6240\6709\4F7F\7528\8005\77AD\89E3\9801\9762\7684\7528\9014\81F3\95DC\91CD\8981, \7279\5225\662F\4F7F\7528\50CF\87A2\5E55\52A9\8B80\7A0B\5F0F\4E4B\985E\7B49\8F14\52A9\6280\8853\7684\4F7F\7528\8005. \7531\65BC\9801\9762\6A19\984C\901A\5E38\662F\87A2\5E55\52A9\8B80\7A0B\5F0F\4F7F\7528\8005\4E00\958B\59CB\807D\5230\7684\5167\5BB9, \56E0\6B64\5FC5\9808\78BA\4FDD\6BCF\500B\9801\9762\6A19\984C\90FD\6709\5176\610F\7FA9\8207\7368\7279\6027.</p>'),
unistr('<p>\6700\4F73\505A\6CD5:</p>'),
'<ol>',
unistr('<li>\6E05\6670\4E14\5177\63CF\8FF0\6027:'),
unistr('\4F7F\7528\7279\5B9A\6A19\984C (\4F8B\5982\300C\77AD\89E3 WCAG 2.1\300D) \6216\5340\6BB5\6A19\984C\8B93\5C0E\89BD\66F4\8F15\9B06.</li>'),
unistr('<li>\6709\6548\6027:'),
unistr('\4EE5\4E0B\5217\7BC4\4F8B\70BA\4F8B: \5047\8A2D\6709\4E00\500B\8868\55AE\9801\9762, \5176\4E2D\5305\542B\50CF\662F\7DE8\8F2F\4E2D\8A18\9304\7684\76F8\95DC\8CC7\8A0A, \4F8B\5982\300C\5EFA\7ACB / \7DE8\8F2F\5BA2\6236: [\5BA2\6236\540D\7A31]\300D. \8ACB\5728\300C\9801\9762\8A2D\8A08\5DE5\5177\300D\57F7\884C\4EE5\4E0B\6B65\9A5F:'),
'<ol>',
unistr('<li>\5F9E\300C\5448\73FE\300D\6A39\72C0\7D50\69CB\4E2D\9078\53D6\9801\9762.</li>'),
unistr('<li>\5728\300C\7279\6027\7DE8\8F2F\5668\300D\4E2D, \627E\51FA\300C\8B58\5225 - \6A19\984C\300D\6B04\4F4D.</li>'),
unistr('<li>\5C07 P1_CUSTOMER_NAME \53D6\4EE3\70BA\5305\542B\8A18\9304 ID \7684\9069\7576\9801\9762\9805\76EE.</li>'),
unistr('<li>\8F38\5165\4EE5\4E0B\6A19\984C\683C\5F0F: \5EFA\7ACB / \7DE8\8F2F\5BA2\6236: &P1_CUSTOMER_NAME. (\5305\62EC\53E5\865F).</li>'),
'</ol>',
'</li>',
'</ol>',
unistr('<p>\5BE6\884C\63CF\8FF0\6027\9801\9762\548C\5340\57DF\6A19\984C\53EF\986F\8457\63D0\6607\8F14\52A9\529F\80FD, \8B93\4F7F\7528\8005\80FD\5920\5728\4E0D\540C\7684 Web \74B0\5883\4E2D\9806\5229\5C0E\89BD\4E26\7406\89E3\5167\5BB9.</p>')))
,p_version_scn=>2566088
);
