unistr('<div style="padding:20px; font-size: 12px;"><p>APEX \5075\6E2C\5230\60A8\7684\5DE5\4F5C\5340\5305\542B 2 \500B\6216\66F4\591A\6709 NULL URI \524D\7F6E\78BC\7684 APEX \5F0F REST \6A21\7D44. ORDS \4E0D\5141\8A31\8D85\904E\4E00\500B\6A21\7D44\5177\6709\76F8\540C\7684\57FA\790E URI \524D\7F6E\78BC. </p>'),
'',
unistr('<p>\70BA\4E86\5C07\9019\4E9B\670D\52D9\79FB\8F49\81F3 ORDS, \5C07\5957\7528\4E0B\5217\898F\5247: </p>'),
'',
'<ul>',
unistr('<li>\6240\6709\53D7\5F71\97FF\7684\6A21\7D44\90FD\5C07\5408\4F75\6210\55AE\4E00\500B\540D\70BA <em><strong>merged.apex.rest.services</strong></em> \7684 ORDS \6A21\7D44.</li>'),
unistr('<li>\82E5 <strong><em>\4EFB\4E00\500B</em></strong>\76EE\524D\5408\4F75\4E2D\7684 APEX \5F0F\6A21\7D44\5DF2\767C\5E03, \65B0\7684\5408\4F75\6A21\7D44\4E5F<strong><em>\5C07\6703\767C\5E03</em></strong>.</li>'),
unistr('<li>\82E5\76EE\524D\5408\4F75\4E2D\7684 APEX \5F0F\6A21\7D44<strong><em>\90FD\672A</em></strong>\767C\5E03, \65B0\7684\5408\4F75\6A21\7D44<strong><em>\5C07\4E0D\6703\767C\5E03</em></strong>.</li>'),
unistr('<li>\76EE\524D\5408\4F75\4E2D APEX \5F0F\6A21\7D44\7684<strong><em>\6240\6709\89D2\8272</em></strong><strong><em>\5C07\6703\6307\5B9A\7D66\65B0\7684\5408\4F75\6A21\7D44</em></strong>.</li>'),
unistr('<li>\5408\4F75\6A21\7D44\7684<strong><em>\5206\9801\5927\5C0F</em></strong>\5C07\8A2D\70BA\5408\4F75\4E2D\6A21\7D44\7684<strong><em>\6700\5927\5206\9801\5927\5C0F</em></strong>.</li>'),
unistr('<li>\5982\679C\5177\6709 NULL \57FA\790E URI \7684 APEX \6A21\7D44\4E5F\64C1\6709\91CD\8907\7684\6A23\677F URI, \5C07\6703\51FA\73FE\4EE5\4E0B\60C5\6CC1:'),
'',
'<ul>',
unistr('<li>\6700\8FD1\66F4\65B0\7684\6A23\677F\5C07\4FDD\7559\91CD\8907\7684 URI</li>'),
unistr('<li>\6240\6709\5176\4ED6\6A23\677F\7684\524D\9762\5C07\52A0\4E0A dup001_* \524D\7F6E\78BC</li>'),
unistr('<li>\6A23\677F\7684\8A3B\89E3\5C07\5305\542B\539F\59CB\7684\6A21\7D44\540D\7A31 (\79FB\8F49\4F86\6E90) \548C\539F\59CB\7684\6A23\677F URI</li>'),
'</ul></li>',
'</ul>',
'</div>',
'<hr/>'))
