,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\60A8\53EF\4EE5\4F7F\7528\6B64\9801\9762\63A7\5236 Oracle APEX \5DE5\4F5C\5340\7BA1\7406\54E1\3001\61C9\7528\7A0B\5F0F\958B\767C\4EBA\54E1\548C\4E00\822C\4F7F\7528\8005\7684\5B58\53D6\6B0A.</p>'),
'',
unistr('<p><strong>\5DE5\4F5C\5340\7BA1\7406\54E1</strong>\53EF\4EE5\5EFA\7ACB\53CA\4FEE\6539\61C9\7528\7A0B\5F0F\548C\8CC7\6599\5EAB\7269\4EF6, \4EE5\53CA\7BA1\7406\4F7F\7528\8005\5E33\6236\3001\7FA4\7D44\548C\958B\767C\670D\52D9.</p>'),
'',
unistr('<p><strong>\958B\767C\4EBA\54E1</strong>\53EF\4EE5\5EFA\7ACB\53CA\4FEE\6539\61C9\7528\7A0B\5F0F\548C\8CC7\6599\5EAB\7269\4EF6.</p>'),
'',
unistr('<p><strong>\4E00\822C\4F7F\7528\8005</strong>\6C92\6709\958B\767C\6B0A\9650, \53EA\80FD\5B58\53D6\672A\4F7F\7528\5916\90E8\8A8D\8B49\914D\7F6E\7684\61C9\7528\7A0B\5F0F.</p>'),
