,p_message_language=>'zh-tw'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\60A8\53EF\4EE5\4F7F\7528\6B64\9801\9762\63A7\5236 Oracle APEX \4E00\822C\4F7F\7528\8005\7684\5B58\53D6\6B0A.</p>'),
'',
unistr('<p><strong>\4E00\822C\4F7F\7528\8005</strong>\4E0D\5177\6709\958B\767C\6B0A\9650, \53EA\80FD\5B58\53D6\672A\4F7F\7528\5916\90E8\8A8D\8B49\914D\7F6E\7684\61C9\7528\7A0B\5F0F.</p>'),
'',
unistr('<p>\60A8\53EF\4EE5\4F7F\7528\8B58\5225\4E3B\63A7\53F0\4F86\7BA1\7406<strong>\5DE5\4F5C\5340\7BA1\7406\54E1</strong>\548C<strong>\958B\767C\4EBA\54E1</strong>. \53EA\8981\5DE5\4F5C\5340\7BA1\7406\54E1\6216\958B\767C\4EBA\54E1\767B\5165 APEX, \7CFB\7D71\5C31\6703\5EFA\7ACB\300C\5F71\5B50\300D\5E33\6236. \60A8\53EF\4EE5\8996\9700\8981\79FB\9664\9019\4E9B\300C\5F71\5B50\300D\4F7F\7528\8005.</p>')))
