,p_version_scn=>7414340
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\6B64\9805\76EE\985E\578B\63D0\4F9B\300C\5730\7406\7DE8\78BC\300D\529F\80FD (\5C07\90F5\5BC4\5730\5740\8F49\63DB\6210\5EA7\6A19).<p>'),
unistr('<p>\5730\7406\7DE8\78BC\662F\7531\5411 <strong>Oracle Elocation</strong> Geocoding Service (elocation.oracle.com) \63D0\51FA REST \8981\6C42\7684<em>\700F\89BD\5668</em>\6240\57F7\884C. \56E0\6B64, \5FC5\9808\5C07\700F\89BD\5668\9023\81F3\7DB2\969B\7DB2\8DEF, \5730\7406\7DE8\78BC\624D\80FD\904B\4F5C.</p>'),
unistr('<p>\5730\7406\7DE8\78BC\8F38\5165\8CC7\6599\53D6\81EA\65BC\8207\5730\5740\90E8\5206 (\4F8B\5982\8857\9053\3001\9580\724C\865F\78BC\3001\90F5\905E\5340\865F\6216\7E23/\5E02) \5C0D\61C9\7684\5176\4ED6\9801\9762\9805\76EE.\300C\5730\7406\7DE8\78BC\5668\300D\6703\986F\793A\4E00\500B\5F48\51FA\5F0F\8996\7A97, \5167\542B\53EF\80FD\7684\76F8\7B26\9805\76EE\6E05\55AE. \7576\60A8\9078\64C7\76F8\7B26\7684\9805\76EE\5F8C, \8A72\9805\76EE\7684\968E\6BB5\4F5C\696D\72C0\614B\503C\6703\8B8A\6210 GeoJSON \683C\5F0F\7684\5730\5740\5EA7\6A19. \82E5\555F\7528<strong>\8655\7406\5730\5740</strong>, \5730\5740\90E8\5206\9801\9762\9805\76EE\6703\4EE5\5730\7406\7DE8\78BC\670D\52D9\6240\9001\51FA\4E26\8655\7406\904E\7684\503C\8986\5BEB.</p>'),
unistr('<p>\91DD\5C0D\6BD4\8F03\7C21\55AE\7684\4F7F\7528\72C0\6CC1\6642, <strong>\975E\7D50\69CB\5316\5730\5740</strong>\6A21\5F0F\53EF\4EE5\53EA\5C0D\61C9\4E00\500B\6587\5B57\6B04\4F4D\6216\4E00\500B\6587\5B57\5340, \4E00\822C\4F7F\7528\8005\53EF\5728\6B64\8F38\5165\5730\5740\90E8\5206 (\4F7F\7528\9017\865F\5340\9694). \5728\6B64\60C5\6CC1\4E0B, <strong>\8655\7406\5730\5740</strong>\6A21\5F0F\7121\6CD5\4F7F\7528.</p>')))
);
