,p_return_value=>'APEX_APPLICATION_TEMP_FILES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\5C07\4E0A\50B3\7684\6A94\6848\5132\5B58\5728\60A8\53EF\4EE5\4F7F\7528 APEX_APPLICATION_TEMP_FILES \6AA2\8996\5B58\53D6\7684\66AB\6642\4F4D\7F6E. &PRODUCT_NAME. \6703\6839\64DA\60A8\9078\64C7\7684<strong>\6C38\4E45\6E05\9664\6A94\6848\6642\9593</strong>\503C, \5728\968E\6BB5\4F5C\696D\7D50\675F\6216\5728\4E0A\50B3\8981\6C42\7D50\675F\6642\81EA\52D5\5C07\6A94\6848\522A\9664.</p>'),
unistr('<p>\82E5\8981\5728<strong>\5141\8A31\591A\500B\6A94\6848</strong>\8A2D\70BA<strong>\5426</strong>\6642\5B58\53D6\6A94\6848:</p>'),
'<pre>',
'select *',
'  from apex_application_temp_files',
' where name = :<em>page item name</em>;',
'</pre>',
unistr('<p>\82E5\8981\5728<strong>\5141\8A31\591A\500B\6A94\6848</strong>\8A2D\70BA<strong>\662F</strong>\6642\5B58\53D6\6A94\6848:</p>'),
'<pre>',
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'    l_file_names := apex_string.split (',
'                        p_str => :<em>page item name</em>,',
'                        p_sep => '':'' );',
'    for i in 1 .. l_file_names.count loop',
'        select *',
'          into l_file',
'          from apex_application_temp_files',
'         where name = l_file_names(i);',
'        -- add code here to store the uploaded file in your own table',
'    end loop;',
'end;',
'</pre>'))
);
