unistr('<p>\5728\4E0A\50B3\7684 XLSX \6A94\6848\4E2D\986F\793A\53EF\7528\5DE5\4F5C\8868\7684\9078\53D6\6E05\55AE\6216\5F48\51FA\5F0F LOV \9805\76EE\6703\4F7F\7528\4EE5\4E0B<em>\503C\6E05\55AE SQL \67E5\8A62</em> (<strong>PX_FILE</strong> \662F\7528\4F86\4E0A\50B3 XLSX \6A94\6848\7684\6A94\6848\700F\89BD\9805\76EE).</p><p>\8ACB\6CE8\610F, <strong>SHEET_FILE_NAME</strong> \5C6C\6027\5FC5\9808\4EE5 LOV \50B3\56DE\8CC7\6599\6B04\7684\65B9\5F0F\4F7F\7528.</p>'),
'<pre>',
'select s.sheet_display_name display, ',
'       s.sheet_file_name    return',
'  from apex_application_temp_files f,',
'       table( <strong>apex_data_parser.get_xlsx_worksheets</strong>( p_content => f.blob_content ) ) s',
' where f.name = :PX_FILE',
'</pre>'))
,p_help_text=>unistr('<p>\63D0\4F9B\5167\542B\5DE5\4F5C\8868\540D\7A31\4EE5\8F09\5165 XLSX \6A94\6848\7684\9801\9762\9805\76EE. \8CC7\6599\5C07\5F9E\6307\5B9A\7684\5DE5\4F5C\8868\8F09\5165. \82E5\672A\63D0\4F9B, APEX \5C07\6703\5F9E XLSX \6A94\6848\4E2D\7684\7B2C\4E00\500B\5DE5\4F5C\8868\8F09\5165\8CC7\6599.</p><p><em>\9078\53D6\6E05\55AE</em>\9805\76EE\901A\5E38\6703\7528\65BC\6B64: \5728<em>\503C\6E05\55AE\67E5\8A62</em>\4E2D, \4F7F\7528 <strong>APEX_DATA_PARSER.GET_XLSX_WORKSHEETS</strong> \4EE5\4FBF\64F7\53D6\5DE5\4F5C\8868\7684\986F\793A\540D\7A31\548C\5167\90E8\540D\7A31.</p>')
