wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(353179625368369848.4418)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033.4418)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>unistr('\611F\6E2C\51FD\6578\540D\7A31')
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\5728\300CPL/SQL \7A0B\5F0F\78BC\300D\5167, \6307\5B9A\50B3\56DE\5E03\6797\503C\7684 PL/SQL \7A0B\5F0F\78BC -</p>'),
'<pre>',
'function sentry_basic_auth',
'return boolean',
'is',
'    c_auth_header   constant varchar2(4000) := owa_util.get_cgi_env(''AUTHORIZATION'');',
'    l_user_pass     varchar2(4000);',
'    l_separator_pos pls_integer;',
'begin',
'    if apex_application.g_user <> ''nobody'' then',
'        return true;',
'    end if;',
'',
'    if c_auth_header like ''Basic %'' then',
'        l_user_pass := utl_encode.text_decode (',
'                           buf      => substr(c_auth_header, 7),',
'                           encoding => utl_encode.base64 );',
'        l_separator_pos := instr(l_user_pass, '':'');',
'        if l_separator_pos > 0 then',
'            apex_authentication.login (',
'                p_username => substr(l_user_pass, 1, l_separator_pos-1),',
'                p_password => substr(l_user_pass, l_separator_pos+1) );',
'            return true;',
'        end if;',
'    end if;',
'',
'    return false;',
'end sentry_basic_auth;',
'</pre>',
unistr('<p>\6307\5B9A PL/SQL \8CC7\6599\5EAB\51FD\6578 - </p>'),
'<pre>',
'sentry_basic_auth',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\8F38\5165 &PRODUCT_NAME. \5F15\64CE\6536\5230\5C0D\5176\63D0\51FA\4E4B\4EFB\4F55\8981\6C42\7684\958B\982D (\4F8B\5982\5728\986F\793A\6216\8655\7406\6BCF\4E00\9801\4E4B\524D\6216\767C\51FA AJAX \8981\6C42\4E4B\524D) \6240\57F7\884C\4E4B\51FD\6578\7684\540D\7A31. '),
unistr('\6B64\51FD\6578\53EF\4EE5\5B9A\7FA9\5728\8A8D\8B49\7684\300CPL/SQL \7A0B\5F0F\78BC\300D\4E2D\3001\5957\88DD\7A0B\5F0F\5167, \6216\8005\5B9A\7FA9\70BA\9810\5B58\51FD\6578.</p>'),
unistr('<p>\5982\679C\6B64\51FD\6578\50B3\56DE false (\4EE3\8868\4F7F\7528\8005\6216\8A31\672A\767B\5165), \5C31\6703\5C07\968E\6BB5\4F5C\696D\6A19\793A\70BA\7121\6548, \4E26\4E14\5C07\6703\547C\53EB<em>\7121\6548\7684\968E\6BB5\4F5C\696D\7A0B\5E8F</em>.'),
