,p_depending_on_expression=>'Y'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
unistr('<dt>\53EA\6709\958B\59CB\65E5\671F\7684\7BC4\4F8B (\91DD\5C0D\4E0D\662F\4EE5\6301\7E8C\6642\9593\70BA\57FA\790E\7684\4E8B\4EF6)</dt>'),
'<dd><pre>',
'begin',
'    update emp',
'       set hiredate = to_date(:APEX$NEW_START_DATE, ''YYYYMMDDHH24MISS'')',
'     where empno = :APEX$PK_VALUE;',
'end;',
'</pre></dd>',
unistr('<dt>\6709\958B\59CB\8207\7D50\675F\65E5\671F\7684\7BC4\4F8B (\91DD\5C0D\4EE5\6301\7E8C\6642\9593\70BA\57FA\790E\7684\4E8B\4EF6)</dt>'),
'<dd><pre>',
'begin',
'    update projects',
'       set start_date = to_date(:APEX$NEW_START_DATE, ''YYYYMMDDHH24MISS''),',
