'     where id = :APEX$PK_VALUE;',
'end;',
'</pre></dd>',
'</dl>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\8F38\5165\884C\4E8B\66C6\9805\76EE\82E5\4F7F\7528\62D6\653E\529F\80FD\66F4\65B0\6642, \7528\4F86\66F4\65B0\76F8\95DC\8868\683C\6216\53EF\66F4\65B0\8996\89C0\8868\7684 PL/SQL \7A0B\5F0F\78BC.</p>'),
unistr('<p>\5982\679C\6B64\884C\4E8B\66C6\986F\793A\6301\7E8C\6642\9593\5F0F\4E8B\4EF6 (\900F\904E\9078\53D6\300C\7D50\675F\65E5\671F\300D\8CC7\6599\6B04), \5247 PL/SQL \7A0B\5F0F\78BC\4E5F\9700\8981\66F4\65B0\9019\500B\503C. \5982\679C\62D6\66F3\6574\500B\4E8B\4EF6, \5247\7531\300C\7D50\675F\65E5\671F\300D\7DAD\8B77\76EE\524D\7684\6301\7E8C\6642\9593. \5982\679C\62D6\66F3\4E8B\4EF6\7684\7D50\5C3E, \5247\6703\66F4\65B0\4E8B\4EF6\7684\6301\7E8C\6642\9593. \5728\6B64\985E\60C5\6CC1\4E2D, \958B\59CB\65E5\671F\5C07\7DAD\6301\4E0D\8B8A, \4F46\662F\6703\66F4\65B0\7D50\675F\65E5\671F\4EE5\53CD\6620\4FEE\8A02\5F8C\7684\6301\7E8C\6642\9593.</p>'),
unistr('<p>\884C\4E8B\66C6\66FF\4EE3\8B8A\6578\5305\62EC:</p>'),
'<dl>',
'  <dt>APEX$NEW_START_DATE</dt>',
unistr('    <dd>\50B3\56DE\4FEE\8A02\5F8C\7684\958B\59CB\65E5\671F. \5373\4F7F\6B64\884C\4E8B\66C6\7684<em>\986F\793A\6642\9593</em>\70BA<strong>\5426</strong>, \65E5\671F\683C\5F0F\4ECD\6703\662F <code>''YYYYMMDDHH24MISS''</code>.</dd>'),
'  <dt>APEX$NEW_END_DATE</dt>',
unistr('    <dd>\50B3\56DE\6301\7E8C\6642\9593\5F0F\4E8B\4EF6\7684\4FEE\8A02\5F8C\7D50\675F\65E5\671F. \5373\4F7F\6B64\884C\4E8B\66C6\7684<em>\986F\793A\6642\9593</em>\70BA<strong>\5426</strong>, \65E5\671F\683C\5F0F\4ECD\6703\662F <code>''YYYYMMDDHH24MISS''</code>.</dd>'),
'  <dt>APEX$PK_VALUE</dt>',
unistr('    <dd>\50B3\56DE\300C\4E3B\7D22\5F15\9375\8CC7\6599\6B04\300D\4E2D\6307\5B9A\4E4B\8CC7\6599\6B04\7684\503C.</dd>'),
'</dl>'))
);
