,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\50C5\9650\9032\968E\4F7F\7528.</p>'),
unistr('<p>\60A8\4E5F\53EF\4EE5\900F\904E\300C\5B8C\6574\300D\5DE5\5177\5217\4E2D\7684\300CHTML \5167\5D4C\300D\529F\80FD, \5167\5D4C\81EA\8A02 HTML \7A0B\5F0F\78BC\7247\6BB5. \6B64\70BA\504F\597D\7684\66FF\4EE3\65B9\6CD5.</p>'),
unistr('<p>\9019\53EA\662F\70BA\4E86\63D0\4F9B\8207 CKEditor4 \6240\7522\751F HTML \6216\4E00\822C\4F7F\7528\8005\624B\52D5\5EFA\7ACB\4E4B HTML \7684\56DE\6EAF\76F8\5BB9\6027, \56E0\6B64\9664\975E\5FC5\8981, \5426\5247\61C9\5C07\9019\9805\8A2D\5B9A\505C\7528.</p>'),
unistr('<p>\9019\9805\8A2D\5B9A\63A7\5236\662F\5426\555F\7528\300C\4E00\822C HTML \652F\63F4\300D(GHS) \548C\300C\4F86\6E90\7DE8\8F2F\300D\7A0B\5F0F\5EAB Plugin.\300C\4F86\6E90\7DE8\8F2F\300D\63D0\4F9B\624B\52D5\8B8A\66F4\57FA\790E HTML \7684\80FD\529B, \800C\300C\4E00\822C HTML \652F\63F4\300D\5247\5141\8A31\4F7F\7528\4EFB\4F55\5176\4ED6\5C08\5C6C\7A0B\5F0F\5EAB Plugin \672A\660E\78BA\652F\63F4\7684 HTML \529F\80FD. \4F8B\5982, <code>iframe</code> \6216 <code>video</code> \4E4B\985E\7684 HTML \5143\7D20, \6216\662F <code>id</code> \4E4B\985E\7684\81EA\8A02 HTML \5C6C\6027, \5982\679C\662F\900F\904E\300C\4F86\6E90\7DE8\8F2F\300D\529F\80FD\65B0\589E, \9664\975E\5DF2\555F\7528\6B64\5C6C\6027, \5426\5247\901A\5E38\6703\88AB')
||unistr('\53BB\9664.</p>'),
unistr('<p>\57FA\672C\4E0A,\300C\4E00\822C HTML \652F\63F4\300DPlugin \6703\8A2D\5B9A\5982\4E0B:'),
'<pre><code>htmlSupport: {',
'    allow: [ {',
'        name: /.*/,',
'        attributes: true,',
'        classes: true,',
'        styles: true',
'    } ]',
'}</code></pre></p>',
unistr('<p>\5982\9700\66F4\7CBE\7D30\7684\63A7\5236, \5EFA\8B70\60A8\5C07\6B64\8A2D\5B9A\95DC\9589, \6539\70BA\900F\904E\521D\59CB\5316 JavaScript \51FD\6578\9032\884C\8A2D\5B9A. \4F8B\5982:'),
'<pre><code>function( options ) {',
'',
'    options.editorOptions.extraPlugins.push (',
'        CKEditor5.sourceEditing.SourceEditing,',
'        CKEditor5.htmlSupport.GeneralHtmlSupport,',
'        CKEditor5.htmlSupport.HtmlComment',
'    );',
'',
'    options.editorOptions.toolbar.items.push( "sourceEditing" );',
'',
'    options.editorOptions.htmlSupport = {',
'        allow: [ {',
'            name: /.*/,',
'            attributes: true,',
'            classes: true,',
'            styles: true',
'        } ]',
'    };',
'',
'    return options;',
'}</code></pre></p>'))
);
