,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<dl><dt>\70BA\7B26\5408\52A0\85AA\8CC7\683C\7684\54E1\5DE5\63D0\9AD8 3% \7684\85AA\8CC7:</dt>'),
'<dd><pre>',
'var rows;',
'function needsSalaryRaise( empno ) {',
unistr('  // \7528\65BC\8A08\7B97\54E1\5DE5\662F\5426\9700\8981\52A0\85AA\7684\8907\96DC\908F\8F2F\9810\7559\4F4D\7F6E'),
'  return true;',
'}',
'rows = apex.conn.execute( "select empno from emp where deptno = :deptno", { deptno: apex.env.P2_DEPTNO } ).rows;',
'for ( var row of rows ) {',
'  if ( needsSalaryRaise( row.EMPNO )) {',
'    apex.conn.execute( "update emp set sal = sal * 1.03 where empno = :empno", { empno: row.EMPNO } );',
'  }',
'}',
'</pre></dd>',
'</dl>',
unistr('<p>\5728\6B64\7BC4\4F8B\4E2D, \60A8\5FC5\9808\5728<strong>\8981\9001\51FA\7684\9805\76EE</strong>\4E2D\8F38\5165 <code>P2_DEPTNO</code>.</p>')))
